-- 1.1 CREATE DATABASE
DROP DATABASE IF EXISTS digital_payment_db;
CREATE DATABASE digital_payment_db;

-- 1.2 USE DATABASE
USE digital_payment_db;

-- 1.3 CREATE TABLES
CREATE TABLE transactions (
    transaction_id  VARCHAR(20)    NOT NULL,
    customer_id     VARCHAR(20)    NOT NULL,
    payment_method  VARCHAR(20)    NOT NULL,
    gateway_name    VARCHAR(20)    NOT NULL,
    amount          DECIMAL(12,2)  NOT NULL,
    status          VARCHAR(10)    NOT NULL,  
    error_code      VARCHAR(30)    NOT NULL,
    created_at      DATETIME       NOT NULL,
    updated_at      DATETIME       NOT NULL,
    PRIMARY KEY (transaction_id)
);

CREATE TABLE payment_retries (
    retry_id                 VARCHAR(20)    NOT NULL,
    original_transaction_id  VARCHAR(20)    NOT NULL,
    attempt_number           INT            NOT NULL,
    retry_status             VARCHAR(10)    NOT NULL,
    time_diff_minutes        INT            NOT NULL,
    recovered_amount         DECIMAL(12,2)  NOT NULL,
    PRIMARY KEY (retry_id),
    CONSTRAINT fk_retry_txn FOREIGN KEY (original_transaction_id)
        REFERENCES transactions (transaction_id)
);

CREATE TABLE refunds_settlements (
    refund_id          VARCHAR(20)    NOT NULL,
    transaction_id     VARCHAR(20)    NOT NULL,
    refund_amount      DECIMAL(12,2)  NOT NULL,
    refund_status      VARCHAR(15)    NOT NULL,   
    settlement_id      VARCHAR(20)    NULL,       
    settlement_status  VARCHAR(15)    NOT NULL,   
    requested_at       DATETIME       NOT NULL,
    PRIMARY KEY (refund_id),
    CONSTRAINT fk_refund_txn FOREIGN KEY (transaction_id)
        REFERENCES transactions (transaction_id)
);

