-- PART 2 | DATA PROFILING
USE digital_payment_db;

-- 1.1 Row count per table
SELECT 'transactions' AS table_name, COUNT(*) AS total_rows FROM transactions
UNION ALL SELECT 'payment_retries',     COUNT(*) FROM payment_retries
UNION ALL SELECT 'refunds_settlements', COUNT(*) FROM refunds_settlements;

-- 1.2 Column metadata (name, type, nullability, key)
SELECT table_name, ordinal_position AS pos, column_name, column_type,
       is_nullable, column_key
FROM   information_schema.columns
WHERE  table_schema = 'digital_payment_db'
  AND  table_name IN ('transactions','payment_retries','refunds_settlements')
ORDER  BY table_name, ordinal_position;

-- 2.1 transactions
SELECT COUNT(*) AS total_rows,
  SUM(transaction_id IS NULL OR TRIM(transaction_id) = '') AS transaction_id_missing,
  SUM(customer_id    IS NULL OR TRIM(customer_id)    = '') AS customer_id_missing,
  SUM(payment_method IS NULL OR TRIM(payment_method) = '') AS payment_method_missing,
  SUM(gateway_name   IS NULL OR TRIM(gateway_name)   = '') AS gateway_name_missing,
  SUM(amount         IS NULL)                              AS amount_missing,
  SUM(status         IS NULL OR TRIM(status)         = '') AS status_missing,
  SUM(error_code     IS NULL OR TRIM(error_code)     = '') AS error_code_missing,
  SUM(created_at     IS NULL)                              AS created_at_missing,
  SUM(updated_at     IS NULL)                              AS updated_at_missing
FROM transactions;

-- 2.2 payment_retries
SELECT COUNT(*) AS total_rows,
  SUM(retry_id                IS NULL OR TRIM(retry_id) = '')                AS retry_id_missing,
  SUM(original_transaction_id IS NULL OR TRIM(original_transaction_id) = '') AS original_transaction_id_missing,
  SUM(attempt_number          IS NULL)                                       AS attempt_number_missing,
  SUM(retry_status            IS NULL OR TRIM(retry_status) = '')            AS retry_status_missing,
  SUM(time_diff_minutes       IS NULL)                                       AS time_diff_minutes_missing,
  SUM(recovered_amount        IS NULL)                                       AS recovered_amount_missing
FROM payment_retries;

-- 2.3 refunds_settlements  (settlement_id NULL is EXPECTED for unsettled refunds)
SELECT COUNT(*) AS total_rows,
  SUM(refund_id         IS NULL OR TRIM(refund_id) = '')         AS refund_id_missing,
  SUM(transaction_id    IS NULL OR TRIM(transaction_id) = '')    AS transaction_id_missing,
  SUM(refund_amount     IS NULL)                                 AS refund_amount_missing,
  SUM(refund_status     IS NULL OR TRIM(refund_status) = '')     AS refund_status_missing,
  SUM(settlement_id     IS NULL OR TRIM(settlement_id) = '')     AS settlement_id_null_or_blank,
  SUM(settlement_status IS NULL OR TRIM(settlement_status) = '') AS settlement_status_missing,
  SUM(requested_at      IS NULL)                                 AS requested_at_missing
FROM refunds_settlements;


-- 3.1 Key uniqueness (total = distinct means no duplicate keys)
SELECT 'transactions.transaction_id' AS key_column, COUNT(*) AS total_values,
       COUNT(DISTINCT transaction_id) AS distinct_values,
       COUNT(*) - COUNT(DISTINCT transaction_id) AS duplicates FROM transactions
UNION ALL
SELECT 'payment_retries.retry_id', COUNT(*), COUNT(DISTINCT retry_id),
       COUNT(*) - COUNT(DISTINCT retry_id) FROM payment_retries
UNION ALL
SELECT 'refunds_settlements.refund_id', COUNT(*), COUNT(DISTINCT refund_id),
       COUNT(*) - COUNT(DISTINCT refund_id) FROM refunds_settlements
UNION ALL
SELECT 'refunds_settlements.settlement_id (non-null)', COUNT(settlement_id),
       COUNT(DISTINCT settlement_id), COUNT(settlement_id) - COUNT(DISTINCT settlement_id)
FROM refunds_settlements;

-- 3.2 Business-level duplicates: same customer, method, gateway, amount and timestamp
SELECT customer_id, payment_method, gateway_name, amount, created_at, COUNT(*) AS occurrences
FROM   transactions
GROUP  BY customer_id, payment_method, gateway_name, amount, created_at
HAVING COUNT(*) > 1;

-- 3.3 More than one retry row / refund row for the same transaction
SELECT 'retries per transaction > 1' AS check_name, COUNT(*) AS violations
FROM (SELECT original_transaction_id FROM payment_retries
      GROUP BY original_transaction_id HAVING COUNT(*) > 1) d
UNION ALL
SELECT 'refunds per transaction > 1', COUNT(*)
FROM (SELECT transaction_id FROM refunds_settlements
      GROUP BY transaction_id HAVING COUNT(*) > 1) d;

-- 3.4 Cardinality of every categorical / identifier column
SELECT COUNT(DISTINCT customer_id)    AS distinct_customers,
       COUNT(DISTINCT payment_method) AS distinct_payment_methods,
       COUNT(DISTINCT gateway_name)   AS distinct_gateways,
       COUNT(DISTINCT status)         AS distinct_statuses,
       COUNT(DISTINCT error_code)     AS distinct_error_codes
FROM transactions;

-- 4.1 Summary statistics for every numeric column
SELECT 'transactions.amount' AS column_name, COUNT(amount) AS n,
       MIN(amount) AS min_val, MAX(amount) AS max_val,
       ROUND(AVG(amount),2) AS mean_val, ROUND(STDDEV(amount),2) AS std_dev,
       SUM(amount <= 0) AS zero_or_negative
FROM transactions
UNION ALL
SELECT 'payment_retries.recovered_amount', COUNT(recovered_amount),
       MIN(recovered_amount), MAX(recovered_amount),
       ROUND(AVG(recovered_amount),2), ROUND(STDDEV(recovered_amount),2),
       SUM(recovered_amount <= 0) FROM payment_retries
UNION ALL
SELECT 'payment_retries.time_diff_minutes', COUNT(time_diff_minutes),
       MIN(time_diff_minutes), MAX(time_diff_minutes),
       ROUND(AVG(time_diff_minutes),2), ROUND(STDDEV(time_diff_minutes),2),
       SUM(time_diff_minutes <= 0) FROM payment_retries
UNION ALL
SELECT 'refunds_settlements.refund_amount', COUNT(refund_amount),
       MIN(refund_amount), MAX(refund_amount),
       ROUND(AVG(refund_amount),2), ROUND(STDDEV(refund_amount),2),
       SUM(refund_amount <= 0) FROM refunds_settlements;

-- 4.2 Median transaction amount
SELECT ROUND(AVG(amount),2) AS median_amount
FROM (SELECT amount,
             ROW_NUMBER() OVER (ORDER BY amount) AS rn,
             COUNT(*)     OVER ()                AS cnt
      FROM transactions) x
WHERE rn IN (FLOOR((cnt + 1) / 2), CEIL((cnt + 1) / 2));

-- 4.3 Outlier scan: amounts outside mean +/- 3 standard deviations
SELECT COUNT(*) AS outlier_transactions
FROM   transactions
WHERE  ABS(amount - (SELECT AVG(amount)    FROM transactions))
         > 3 * (SELECT STDDEV(amount) FROM transactions);

-- 4.4 Amount distribution in bands of 5,000
SELECT CONCAT(FLOOR(amount/5000)*5000, ' - ', FLOOR(amount/5000)*5000 + 4999) AS amount_band,
       COUNT(*) AS txn_count,
       ROUND(100 * COUNT(*) / (SELECT COUNT(*) FROM transactions), 2) AS pct
FROM   transactions
GROUP  BY amount_band
ORDER  BY MIN(amount);

-- 4.5 Precision check: values with more than 2 decimal places
SELECT 'transactions.amount' AS column_name, SUM(amount <> ROUND(amount,2)) AS bad_precision FROM transactions
UNION ALL SELECT 'payment_retries.recovered_amount', SUM(recovered_amount <> ROUND(recovered_amount,2)) FROM payment_retries
UNION ALL SELECT 'refunds_settlements.refund_amount', SUM(refund_amount <> ROUND(refund_amount,2)) FROM refunds_settlements;

-- 5. CATEGORICAL PROFILE  (value frequencies with % share)
SELECT 'payment_method' AS column_name, payment_method AS value, COUNT(*) AS freq,
       ROUND(100*COUNT(*)/(SELECT COUNT(*) FROM transactions),2) AS pct
FROM transactions GROUP BY payment_method
UNION ALL
SELECT 'gateway_name', gateway_name, COUNT(*), ROUND(100*COUNT(*)/(SELECT COUNT(*) FROM transactions),2)
FROM transactions GROUP BY gateway_name
UNION ALL
SELECT 'status', status, COUNT(*), ROUND(100*COUNT(*)/(SELECT COUNT(*) FROM transactions),2)
FROM transactions GROUP BY status
UNION ALL
SELECT 'error_code', IFNULL(error_code,'<NULL>'), COUNT(*), ROUND(100*COUNT(*)/(SELECT COUNT(*) FROM transactions),2)
FROM transactions GROUP BY error_code
UNION ALL
SELECT 'retry_status', retry_status, COUNT(*), ROUND(100*COUNT(*)/(SELECT COUNT(*) FROM payment_retries),2)
FROM payment_retries GROUP BY retry_status
UNION ALL
SELECT 'attempt_number', CAST(attempt_number AS CHAR), COUNT(*), ROUND(100*COUNT(*)/(SELECT COUNT(*) FROM payment_retries),2)
FROM payment_retries GROUP BY attempt_number
UNION ALL
SELECT 'refund_status', refund_status, COUNT(*), ROUND(100*COUNT(*)/(SELECT COUNT(*) FROM refunds_settlements),2)
FROM refunds_settlements GROUP BY refund_status
UNION ALL
SELECT 'settlement_status', settlement_status, COUNT(*), ROUND(100*COUNT(*)/(SELECT COUNT(*) FROM refunds_settlements),2)
FROM refunds_settlements GROUP BY settlement_status
ORDER BY column_name, freq DESC;

-- 5.2 Status vs error_code cross-tab
SELECT status, IFNULL(error_code,'<NULL>') AS error_code, COUNT(*) AS txn_count
FROM   transactions
GROUP  BY status, error_code
ORDER  BY status, txn_count DESC;

-- 5.3 Payment method vs gateway cross-tab
SELECT payment_method,
       SUM(gateway_name = 'Razorpay') AS Razorpay,
       SUM(gateway_name = 'Cashfree') AS Cashfree,
       SUM(gateway_name = 'PayU')     AS PayU,
       COUNT(*)                       AS total
FROM   transactions
GROUP  BY payment_method;

-- 5.4 Text hygiene: leading/trailing spaces and inconsistent case/spelling
SELECT 'leading/trailing spaces' AS check_name,
       SUM(transaction_id <> TRIM(transaction_id)) + SUM(customer_id <> TRIM(customer_id))
     + SUM(payment_method <> TRIM(payment_method)) + SUM(gateway_name <> TRIM(gateway_name))
     + SUM(status <> TRIM(status)) + SUM(error_code <> TRIM(error_code)) AS issues
FROM transactions
UNION ALL
SELECT 'case/spelling variants (payment_method)',
       COUNT(DISTINCT payment_method) - COUNT(DISTINCT UPPER(TRIM(payment_method))) FROM transactions
UNION ALL
SELECT 'case/spelling variants (gateway_name)',
       COUNT(DISTINCT gateway_name) - COUNT(DISTINCT UPPER(TRIM(gateway_name))) FROM transactions
UNION ALL
SELECT 'literal text "None"/"NULL"/"N/A" in refunds',
       SUM(UPPER(TRIM(settlement_id)) IN ('NONE','NULL','N/A','NA','')) FROM refunds_settlements;

-- 6. FORMAT VALIDATION  (regular expressions; 0 violations expected)
SELECT 'transaction_id  <> TXN_######'  AS check_name, COUNT(*) AS violations FROM transactions        WHERE transaction_id NOT REGEXP '^TXN_[0-9]{6}$'
UNION ALL SELECT 'customer_id     <> CUST_####', COUNT(*) FROM transactions        WHERE customer_id NOT REGEXP '^CUST_[0-9]{4}$'
UNION ALL SELECT 'error_code      <> ERR_*',     COUNT(*) FROM transactions        WHERE error_code NOT REGEXP '^ERR_[A-Z_]+$'
UNION ALL SELECT 'retry_id        <> RTX_######',COUNT(*) FROM payment_retries     WHERE retry_id NOT REGEXP '^RTX_[0-9]{6}$'
UNION ALL SELECT 'retry txn id    <> TXN_######',COUNT(*) FROM payment_retries     WHERE original_transaction_id NOT REGEXP '^TXN_[0-9]{6}$'
UNION ALL SELECT 'refund_id       <> REF_######',COUNT(*) FROM refunds_settlements WHERE refund_id NOT REGEXP '^REF_[0-9]{6}$'
UNION ALL SELECT 'settlement_id   <> SET_######',COUNT(*) FROM refunds_settlements WHERE settlement_id IS NOT NULL AND settlement_id NOT REGEXP '^SET_[0-9]{6}$';

-- 7.1 Date range per table
SELECT 'transactions.created_at' AS column_name, MIN(created_at) AS earliest, MAX(created_at) AS latest,
       DATEDIFF(MAX(created_at), MIN(created_at)) AS span_days FROM transactions
UNION ALL SELECT 'transactions.updated_at', MIN(updated_at), MAX(updated_at),
       DATEDIFF(MAX(updated_at), MIN(updated_at)) FROM transactions
UNION ALL SELECT 'refunds_settlements.requested_at', MIN(requested_at), MAX(requested_at),
       DATEDIFF(MAX(requested_at), MIN(requested_at)) FROM refunds_settlements;

-- 7.2 Volume by month
SELECT DATE_FORMAT(created_at, '%Y-%m') AS month, COUNT(*) AS txns,
       ROUND(SUM(amount),2) AS total_amount
FROM   transactions
GROUP  BY DATE_FORMAT(created_at, '%Y-%m')
ORDER  BY month;

-- 7.3 Volume by hour of day
SELECT HOUR(created_at) AS hour_of_day, COUNT(*) AS txns
FROM   transactions
GROUP  BY HOUR(created_at)
ORDER  BY hour_of_day;

-- 7.4 Processing time (updated_at - created_at, seconds) by status
SELECT status,
       COUNT(*)                                                  AS txns,
       MIN(TIMESTAMPDIFF(SECOND, created_at, updated_at))        AS min_sec,
       ROUND(AVG(TIMESTAMPDIFF(SECOND, created_at, updated_at)),1) AS avg_sec,
       MAX(TIMESTAMPDIFF(SECOND, created_at, updated_at))        AS max_sec
FROM   transactions
GROUP  BY status;

-- 7.5 PENDING transactions grouped by how long they have been stuck
SELECT TIMESTAMPDIFF(SECOND, created_at, updated_at) AS pending_seconds, COUNT(*) AS txns
FROM   transactions
WHERE  status = 'PENDING'
GROUP  BY pending_seconds
ORDER  BY pending_seconds;

-- 8. REFERENTIAL INTEGRITY  (orphan records; 0 expected)
SELECT 'retries with no parent transaction' AS check_name, COUNT(*) AS violations
FROM payment_retries r LEFT JOIN transactions t ON t.transaction_id = r.original_transaction_id
WHERE t.transaction_id IS NULL
UNION ALL
SELECT 'refunds with no parent transaction', COUNT(*)
FROM refunds_settlements f LEFT JOIN transactions t ON t.transaction_id = f.transaction_id
WHERE t.transaction_id IS NULL;

-- 9. BUSINESS-RULE CONSISTENCY  (single summary table; 0 = rule holds)
SELECT 'updated_at earlier than created_at' AS rule_check, COUNT(*) AS violations
FROM transactions WHERE updated_at < created_at
UNION ALL SELECT 'SUCCESS txn carrying an error code', COUNT(*)
FROM transactions WHERE status = 'SUCCESS' AND error_code <> 'ERR_NONE' AND error_code IS NOT NULL
UNION ALL SELECT 'FAILED/PENDING txn with no error code', COUNT(*)
FROM transactions WHERE status <> 'SUCCESS' AND (error_code = 'ERR_NONE' OR error_code IS NULL)
UNION ALL SELECT 'retry on a txn that was not FAILED', COUNT(*)
FROM payment_retries r JOIN transactions t ON t.transaction_id = r.original_transaction_id
WHERE t.status <> 'FAILED'
UNION ALL SELECT 'recovered_amount different from original amount', COUNT(*)
FROM payment_retries r JOIN transactions t ON t.transaction_id = r.original_transaction_id
WHERE r.recovered_amount <> t.amount
UNION ALL SELECT 'refund on a txn that was not SUCCESS', COUNT(*)
FROM refunds_settlements f JOIN transactions t ON t.transaction_id = f.transaction_id
WHERE t.status <> 'SUCCESS'
UNION ALL SELECT 'refund_amount greater than original amount', COUNT(*)
FROM refunds_settlements f JOIN transactions t ON t.transaction_id = f.transaction_id
WHERE f.refund_amount > t.amount
UNION ALL SELECT 'refund requested before txn was created', COUNT(*)
FROM refunds_settlements f JOIN transactions t ON t.transaction_id = f.transaction_id
WHERE f.requested_at < t.created_at
UNION ALL SELECT 'SETTLED refund without settlement_id', COUNT(*)
FROM refunds_settlements WHERE settlement_status = 'SETTLED' AND settlement_id IS NULL
UNION ALL SELECT 'UNSETTLED refund that has a settlement_id', COUNT(*)
FROM refunds_settlements WHERE settlement_status = 'UNSETTLED' AND settlement_id IS NOT NULL
UNION ALL SELECT 'COMPLETED refund not SETTLED', COUNT(*)
FROM refunds_settlements WHERE refund_status = 'COMPLETED' AND settlement_status <> 'SETTLED'
UNION ALL SELECT 'non-COMPLETED refund already SETTLED', COUNT(*)
FROM refunds_settlements WHERE refund_status <> 'COMPLETED' AND settlement_status = 'SETTLED';

-- 10.1 Success / failure / pending rate by gateway
SELECT gateway_name, COUNT(*) AS txns,
       ROUND(100*SUM(status='SUCCESS')/COUNT(*),2) AS success_pct,
       ROUND(100*SUM(status='FAILED')/COUNT(*),2)  AS failed_pct,
       ROUND(100*SUM(status='PENDING')/COUNT(*),2) AS pending_pct,
       ROUND(AVG(amount),2) AS avg_amount
FROM transactions GROUP BY gateway_name ORDER BY success_pct DESC;

-- 10.2 Success / failure / pending rate by payment method
SELECT payment_method, COUNT(*) AS txns,
       ROUND(100*SUM(status='SUCCESS')/COUNT(*),2) AS success_pct,
       ROUND(100*SUM(status='FAILED')/COUNT(*),2)  AS failed_pct,
       ROUND(100*SUM(status='PENDING')/COUNT(*),2) AS pending_pct
FROM transactions GROUP BY payment_method ORDER BY success_pct DESC;

-- 10.3 Retry recovery: share of FAILED transactions that were retried successfully
SELECT (SELECT COUNT(*) FROM transactions WHERE status = 'FAILED')            AS failed_txns,
       (SELECT COUNT(*) FROM payment_retries)                                 AS retried_txns,
       ROUND(100 * (SELECT COUNT(*) FROM payment_retries)
                 / (SELECT COUNT(*) FROM transactions WHERE status = 'FAILED'),2) AS recovery_pct,
       (SELECT ROUND(SUM(recovered_amount),2) FROM payment_retries)           AS total_recovered_amount;

-- 10.4 Refund exposure by refund status
SELECT refund_status, settlement_status, COUNT(*) AS refunds,
       ROUND(SUM(refund_amount),2) AS refund_value
FROM   refunds_settlements
GROUP  BY refund_status, settlement_status
ORDER  BY refunds DESC;

-- 10.5 Customer activity: transactions per customer
SELECT MIN(c) AS min_txns, MAX(c) AS max_txns, ROUND(AVG(c),2) AS avg_txns
FROM  (SELECT customer_id, COUNT(*) AS c FROM transactions GROUP BY customer_id) x;

-- DATA CLEANING
USE digital_payment_db;
SET SQL_SAFE_UPDATES = 0;          

-- IF NOT EXISTS: a second run never overwrites the ORIGINAL backup.
CREATE TABLE IF NOT EXISTS transactions_backup        AS SELECT * FROM transactions;
CREATE TABLE IF NOT EXISTS payment_retries_backup     AS SELECT * FROM payment_retries;
CREATE TABLE IF NOT EXISTS refunds_settlements_backup AS SELECT * FROM refunds_settlements;

DROP TABLE IF EXISTS data_cleaning_log;
CREATE TABLE data_cleaning_log (
    log_id            INT AUTO_INCREMENT PRIMARY KEY,
    step_no           VARCHAR(6)   NOT NULL,
    step_description  VARCHAR(200) NOT NULL,
    table_name        VARCHAR(30)  NOT NULL,
    rows_affected     INT          NOT NULL,
    logged_at         DATETIME     DEFAULT CURRENT_TIMESTAMP
);

-- 1.1 transactions: canonical spelling for payment method and gateway
UPDATE transactions
SET payment_method = CASE UPPER(REPLACE(TRIM(payment_method), ' ', ''))
                         WHEN 'UPI'         THEN 'UPI'
                         WHEN 'CREDITCARD'  THEN 'Credit Card'
                         WHEN 'DEBITCARD'   THEN 'Debit Card'
                         WHEN 'NETBANKING'  THEN 'NetBanking'
                         WHEN 'WALLET'      THEN 'Wallet'
                         ELSE TRIM(payment_method) END,
    gateway_name   = CASE UPPER(TRIM(gateway_name))
                         WHEN 'RAZORPAY'    THEN 'Razorpay'
                         WHEN 'CASHFREE'    THEN 'Cashfree'
                         WHEN 'PAYU'        THEN 'PayU'
                         ELSE TRIM(gateway_name) END;
VALUES ('1.1', 'Standardise payment_method and gateway_name spelling/whitespace', 'transactions', ROW_COUNT());

-- 1.2 transactions: upper-case codes and customer ids
UPDATE transactions
SET customer_id = UPPER(TRIM(customer_id)),
    status      = UPPER(TRIM(status)),
    error_code  = UPPER(TRIM(error_code));
VALUES ('1.2', 'Trim + upper-case customer_id, status, error_code', 'transactions', ROW_COUNT());

-- 1.3 payment_retries
UPDATE payment_retries SET retry_status = UPPER(TRIM(retry_status));
VALUES ('1.3', 'Trim + upper-case retry_status', 'payment_retries', ROW_COUNT());

-- 1.4 refunds_settlements
UPDATE refunds_settlements
SET refund_status     = UPPER(TRIM(refund_status)),
    settlement_status = UPPER(TRIM(settlement_status)),
    settlement_id     = UPPER(TRIM(settlement_id));
VALUES ('1.4', 'Trim + upper-case refund_status, settlement_status, settlement_id', 'refunds_settlements', ROW_COUNT());

-- 2.1 settlement_id: 'None', 'NULL', 'N/A', blank  ->  NULL
UPDATE refunds_settlements
SET    settlement_id = NULL
WHERE  settlement_id IN ('NONE', 'NULL', 'N/A', 'NA', '');
VALUES ('2.1', 'Placeholder text in settlement_id converted to NULL', 'refunds_settlements', ROW_COUNT());

-- 2.2 error_code: the sentinel 'ERR_NONE' means "no error"  ->  NULL
ALTER TABLE transactions MODIFY error_code VARCHAR(30) NULL;
UPDATE transactions SET error_code = NULL WHERE error_code IN ('ERR_NONE', 'NONE', '');
VALUES ('2.2', 'Sentinel ERR_NONE converted to NULL (no error)', 'transactions', ROW_COUNT());

-- STEP 3. REMOVE DUPLICATE TRANSACTIONS
DROP TEMPORARY TABLE IF EXISTS dup_map;
CREATE TEMPORARY TABLE dup_map AS
SELECT t.transaction_id AS dup_id, k.keep_id
FROM   transactions t
JOIN  (SELECT customer_id, payment_method, gateway_name, amount, created_at,
              MIN(transaction_id) AS keep_id
       FROM   transactions
       GROUP  BY customer_id, payment_method, gateway_name, amount, created_at
       HAVING COUNT(*) > 1) k
  ON  k.customer_id    = t.customer_id
  AND k.payment_method = t.payment_method
  AND k.gateway_name   = t.gateway_name
  AND k.amount         = t.amount
  AND k.created_at     = t.created_at
WHERE t.transaction_id <> k.keep_id;

UPDATE payment_retries r JOIN dup_map d ON d.dup_id = r.original_transaction_id
SET    r.original_transaction_id = d.keep_id;
VALUES ('3.1', 'Retries re-pointed from duplicate to surviving transaction', 'payment_retries', ROW_COUNT());

UPDATE refunds_settlements f JOIN dup_map d ON d.dup_id = f.transaction_id
SET    f.transaction_id = d.keep_id;
VALUES ('3.2', 'Refunds re-pointed from duplicate to surviving transaction', 'refunds_settlements', ROW_COUNT());

DELETE t FROM transactions t JOIN dup_map d ON d.dup_id = t.transaction_id;
VALUES ('3.3', 'Duplicate transactions deleted', 'transactions', ROW_COUNT());

DROP TEMPORARY TABLE IF EXISTS dup_map;

-- STEP 4. REMOVE INVALID VALUES  (amounts must be > 0)
DELETE FROM payment_retries
WHERE  recovered_amount <= 0 OR attempt_number < 1 OR time_diff_minutes < 0;
VALUES ('4.1', 'Retries with non-positive amount / invalid attempt / negative delay deleted', 'payment_retries', ROW_COUNT());

DELETE FROM refunds_settlements WHERE refund_amount <= 0;
VALUES ('4.2', 'Refunds with non-positive amount deleted', 'refunds_settlements', ROW_COUNT());

DELETE r FROM payment_retries r JOIN transactions t ON t.transaction_id = r.original_transaction_id
WHERE  t.amount <= 0;
VALUES ('4.3', 'Retries belonging to invalid transactions deleted', 'payment_retries', ROW_COUNT());

DELETE f FROM refunds_settlements f JOIN transactions t ON t.transaction_id = f.transaction_id
WHERE  t.amount <= 0;
VALUES ('4.4', 'Refunds belonging to invalid transactions deleted', 'refunds_settlements', ROW_COUNT());

DELETE FROM transactions WHERE amount <= 0;
VALUES ('4.5', 'Transactions with non-positive amount deleted', 'transactions', ROW_COUNT());

-- STEP 5. FIX LOGICAL INCONSISTENCIES

-- 5.1 updated_at earlier than created_at  ->  swap the two timestamps
UPDATE transactions t
JOIN  (SELECT transaction_id, created_at AS c, updated_at AS u
       FROM   transactions WHERE updated_at < created_at) s
  ON  s.transaction_id = t.transaction_id
SET   t.created_at = s.u,
      t.updated_at = s.c;
VALUES ('5.1', 'Swapped created_at/updated_at where updated_at < created_at', 'transactions', ROW_COUNT());

-- 5.2 refund larger than the original payment  ->  cap at the payment amount
UPDATE refunds_settlements f
JOIN   transactions t ON t.transaction_id = f.transaction_id
SET    f.refund_amount = t.amount
WHERE  f.refund_amount > t.amount;
VALUES ('5.2', 'refund_amount capped at original transaction amount', 'refunds_settlements', ROW_COUNT());

-- 5.3 round money columns to 2 decimals
UPDATE transactions         SET amount           = ROUND(amount, 2);
UPDATE payment_retries      SET recovered_amount = ROUND(recovered_amount, 2);
UPDATE refunds_settlements  SET refund_amount    = ROUND(refund_amount, 2);

-- STEP 6. ANALYSIS-READY VIEW  (derived columns, no change to base tables)
CREATE OR REPLACE VIEW vw_transactions_clean AS
SELECT  t.transaction_id,
        t.customer_id,
        t.payment_method,
        t.gateway_name,
        t.amount,
        t.status,
        t.error_code,
        t.created_at,
        t.updated_at,
        TIMESTAMPDIFF(SECOND, t.created_at, t.updated_at)           AS processing_seconds,
        DATE(t.created_at)                                          AS txn_date,
        DATE_FORMAT(t.created_at, '%Y-%m')                          AS txn_month,
        DAYNAME(t.created_at)                                       AS txn_day,
        HOUR(t.created_at)                                          AS txn_hour,
        CONCAT(FLOOR(t.amount / 5000) * 5000, '-',
               FLOOR(t.amount / 5000) * 5000 + 4999)                AS amount_band,
        CASE WHEN t.status = 'PENDING'
              AND TIMESTAMPDIFF(SECOND, t.created_at, t.updated_at) >= 3600
             THEN 1 ELSE 0 END                                      AS is_stuck_pending,
        CASE WHEN IFNULL(r.successful_retries, 0) > 0 THEN 1 ELSE 0 END AS is_recovered,
        CASE WHEN t.status = 'FAILED' AND IFNULL(r.successful_retries, 0) > 0
             THEN 'RECOVERED' ELSE t.status END                     AS final_status,
        CASE t.error_code WHEN 'ERR_GATEWAY_TIMEOUT'    THEN 'Technical (gateway)'
                          WHEN 'ERR_BANK_DECLINED'      THEN 'Issuer bank'
                          WHEN 'ERR_INSUFFICIENT_FUNDS' THEN 'Customer'
                          WHEN 'ERR_INVALID_OTP'        THEN 'Customer'
                          ELSE NULL END                                        AS failure_category,
        IFNULL(r.recovered_amount, 0)                               AS recovered_amount,
        IFNULL(f.refund_amount, 0)                                  AS refund_amount,
        f.refund_status,
        f.settlement_status
FROM    transactions t
LEFT JOIN (SELECT original_transaction_id,
                  SUM(retry_status = 'SUCCESS')                             AS successful_retries,
                  SUM(CASE WHEN retry_status = 'SUCCESS' THEN recovered_amount END) AS recovered_amount
           FROM   payment_retries GROUP BY original_transaction_id) r
       ON r.original_transaction_id = t.transaction_id
LEFT JOIN (SELECT transaction_id,
                  SUM(refund_amount) AS refund_amount,
                  MAX(refund_status) AS refund_status,
                  MAX(settlement_status) AS settlement_status
           FROM   refunds_settlements GROUP BY transaction_id) f
       ON f.transaction_id = t.transaction_id;

-- =====================================================================
-- STEP 7. OPTIONAL HARD CONSTRAINTS  (run ONCE; keeps future loads clean)
--         MySQL 8.0.16+ / MariaDB 10.2+. Uncomment to enable.
-- =====================================================================
-- ALTER TABLE transactions        ADD CONSTRAINT chk_txn_amount    CHECK (amount > 0);
-- ALTER TABLE transactions        ADD CONSTRAINT chk_txn_status    CHECK (status IN ('SUCCESS','FAILED','PENDING'));
-- ALTER TABLE transactions        ADD CONSTRAINT chk_txn_dates     CHECK (updated_at >= created_at);
-- ALTER TABLE payment_retries     ADD CONSTRAINT chk_retry_amount  CHECK (recovered_amount > 0);
-- ALTER TABLE refunds_settlements ADD CONSTRAINT chk_refund_amount CHECK (refund_amount > 0);

SET SQL_SAFE_UPDATES = 1;

-- =====================================================================
-- STEP 8. VALIDATION
-- =====================================================================

-- 8.1 What the cleaning changed (rows affected per step)
SELECT step_no, table_name, step_description, rows_affected
FROM   data_cleaning_log
ORDER  BY log_id;

-- 8.2 Row counts: before (backup) vs after (cleaned)
SELECT 'transactions' AS table_name,
       (SELECT COUNT(*) FROM transactions_backup)        AS rows_before,
       (SELECT COUNT(*) FROM transactions)               AS rows_after,
       (SELECT COUNT(*) FROM transactions_backup) - (SELECT COUNT(*) FROM transactions) AS rows_removed
UNION ALL
SELECT 'payment_retries',
       (SELECT COUNT(*) FROM payment_retries_backup), (SELECT COUNT(*) FROM payment_retries),
       (SELECT COUNT(*) FROM payment_retries_backup) - (SELECT COUNT(*) FROM payment_retries)
UNION ALL
SELECT 'refunds_settlements',
       (SELECT COUNT(*) FROM refunds_settlements_backup), (SELECT COUNT(*) FROM refunds_settlements),
       (SELECT COUNT(*) FROM refunds_settlements_backup) - (SELECT COUNT(*) FROM refunds_settlements);

-- 8.3 Re-run of the quality rules on the cleaned data (every line should be 0)
SELECT 'duplicate transactions' AS rule_check, COUNT(*) AS violations
FROM (SELECT 1 FROM transactions
      GROUP BY customer_id, payment_method, gateway_name, amount, created_at
      HAVING COUNT(*) > 1) d
UNION ALL SELECT 'non-positive transaction amount', COUNT(*) FROM transactions WHERE amount <= 0
UNION ALL SELECT 'non-positive retry amount',       COUNT(*) FROM payment_retries WHERE recovered_amount <= 0
UNION ALL SELECT 'non-positive refund amount',      COUNT(*) FROM refunds_settlements WHERE refund_amount <= 0
UNION ALL SELECT 'updated_at earlier than created_at', COUNT(*) FROM transactions WHERE updated_at < created_at
UNION ALL SELECT 'placeholder text left in settlement_id', COUNT(*) FROM refunds_settlements
          WHERE settlement_id IN ('NONE','NULL','N/A','NA','')
UNION ALL SELECT 'ERR_NONE sentinel left in error_code', COUNT(*) FROM transactions WHERE error_code = 'ERR_NONE'
UNION ALL SELECT 'refund greater than original amount', COUNT(*)
          FROM refunds_settlements f JOIN transactions t ON t.transaction_id = f.transaction_id
          WHERE f.refund_amount > t.amount
UNION ALL SELECT 'orphan retries', COUNT(*)
          FROM payment_retries r LEFT JOIN transactions t ON t.transaction_id = r.original_transaction_id
          WHERE t.transaction_id IS NULL
UNION ALL SELECT 'orphan refunds', COUNT(*)
          FROM refunds_settlements f LEFT JOIN transactions t ON t.transaction_id = f.transaction_id
          WHERE t.transaction_id IS NULL
UNION ALL SELECT 'SUCCESS txn with an error code', COUNT(*)
          FROM transactions WHERE status = 'SUCCESS' AND error_code IS NOT NULL
UNION ALL SELECT 'FAILED/PENDING txn without error code', COUNT(*)
          FROM transactions WHERE status <> 'SUCCESS' AND error_code IS NULL
UNION ALL SELECT 'SETTLED refund without settlement_id', COUNT(*)
          FROM refunds_settlements WHERE settlement_status = 'SETTLED' AND settlement_id IS NULL
UNION ALL SELECT 'UNSETTLED refund with a settlement_id', COUNT(*)
          FROM refunds_settlements WHERE settlement_status = 'UNSETTLED' AND settlement_id IS NOT NULL;

-- 8.4 Preview of the analysis-ready view
SELECT final_status, COUNT(*) AS txns, SUM(is_stuck_pending) AS stuck_pending,
       ROUND(SUM(amount),2) AS total_amount
FROM   vw_transactions_clean
GROUP  BY final_status
ORDER  BY txns DESC;


-- PART 4-6 | ANALYSIS: CORE + NEW FEATURES + POWER BI
USE digital_payment_db;

-- PART 4 | CORE FAILURE ANALYSIS  (the standard payment-failure project)

CREATE OR REPLACE VIEW vw_data_snapshot AS
SELECT GREATEST((SELECT MAX(updated_at)   FROM transactions),
                (SELECT MAX(requested_at) FROM refunds_settlements)) AS as_of;

-- ---------------------------------------------------------------------
-- 4.1 EXECUTIVE KPI SUMMARY  (headline cards)
-- ---------------------------------------------------------------------
SELECT COUNT(*)                                                    AS total_txns,
       SUM(status = 'SUCCESS')                                     AS success_txns,
       SUM(status = 'FAILED')                                      AS failed_txns,
       SUM(status = 'PENDING')                                     AS pending_txns,
       ROUND(100 * SUM(status = 'SUCCESS') / COUNT(*), 2)          AS success_rate_pct,
       ROUND(100 * SUM(status = 'FAILED')  / COUNT(*), 2)          AS failure_rate_pct,
       ROUND(100 * SUM(status = 'PENDING') / COUNT(*), 2)          AS pending_rate_pct,
       ROUND(SUM(amount), 2)                                       AS gross_attempted_value,
       ROUND(SUM(CASE WHEN status = 'SUCCESS' THEN amount ELSE 0 END), 2) AS successful_value,
       ROUND(SUM(CASE WHEN status = 'FAILED'  THEN amount ELSE 0 END), 2) AS failed_value,
       ROUND(SUM(CASE WHEN status = 'PENDING' THEN amount ELSE 0 END), 2) AS pending_value,
       ROUND(AVG(amount), 2)                                       AS avg_ticket_size,
       COUNT(DISTINCT customer_id)                                 AS unique_customers
FROM   vw_transactions_clean;

-- 4.2 TREND OVER TIME
WITH m AS (
    SELECT txn_month,
           COUNT(DISTINCT txn_date)   AS days_covered,
           COUNT(*)                   AS txns,
           SUM(status = 'FAILED')     AS failed,
           SUM(status = 'PENDING')    AS pending
    FROM   vw_transactions_clean
    GROUP  BY txn_month
)
SELECT txn_month, days_covered, txns, failed, pending,
       ROUND(100 * failed / txns, 2)                AS failure_rate_pct,
       ROUND(100 * (failed + pending) / txns, 2)    AS non_success_rate_pct,
       ROUND(100 * failed / txns
             - LAG(100 * failed / txns) OVER (ORDER BY txn_month), 2) AS mom_failure_change_pp
FROM   m
ORDER  BY txn_month;

-- 4.2b Weekly trend (weeks start on Monday)
SELECT DATE_SUB(txn_date, INTERVAL WEEKDAY(txn_date) DAY)    AS week_start,
       COUNT(*)                                              AS txns,
       SUM(status = 'FAILED')                                AS failed,
       ROUND(100 * SUM(status = 'FAILED')  / COUNT(*), 2)    AS failure_rate_pct,
       ROUND(100 * SUM(status = 'PENDING') / COUNT(*), 2)    AS pending_rate_pct
FROM   vw_transactions_clean
GROUP  BY week_start
ORDER  BY week_start;

-- 4.3 GATEWAY PERFORMANCE SCORECARD
SELECT gateway_name,
       COUNT(*)                                                    AS txns,
       SUM(status = 'SUCCESS')                                     AS success_txns,
       SUM(status = 'FAILED')                                      AS failed_txns,
       SUM(status = 'PENDING')                                     AS pending_txns,
       ROUND(100 * SUM(status = 'SUCCESS') / COUNT(*), 2)          AS success_rate_pct,
       ROUND(100 * SUM(status = 'FAILED')  / COUNT(*), 2)          AS failure_rate_pct,
       ROUND(100 * SUM(status = 'PENDING') / COUNT(*), 2)          AS pending_rate_pct,
       ROUND(SUM(CASE WHEN status = 'FAILED'  THEN amount ELSE 0 END), 2) AS failed_value,
       ROUND(SUM(CASE WHEN status = 'PENDING' THEN amount ELSE 0 END), 2) AS pending_value,
       ROUND(AVG(CASE WHEN status = 'SUCCESS' THEN processing_seconds END), 2) AS avg_success_seconds,
       RANK() OVER (ORDER BY SUM(status = 'SUCCESS') / COUNT(*) DESC)  AS reliability_rank
FROM   vw_transactions_clean
GROUP  BY gateway_name
ORDER  BY reliability_rank;

-- 4.4 PAYMENT METHOD PERFORMANCE SCORECARD
SELECT payment_method,
       COUNT(*)                                                    AS txns,
       SUM(status = 'SUCCESS')                                     AS success_txns,
       SUM(status = 'FAILED')                                      AS failed_txns,
       SUM(status = 'PENDING')                                     AS pending_txns,
       ROUND(100 * SUM(status = 'SUCCESS') / COUNT(*), 2)          AS success_rate_pct,
       ROUND(100 * SUM(status = 'FAILED')  / COUNT(*), 2)          AS failure_rate_pct,
       ROUND(100 * SUM(status = 'PENDING') / COUNT(*), 2)          AS pending_rate_pct,
       ROUND(SUM(CASE WHEN status = 'FAILED'  THEN amount ELSE 0 END), 2) AS failed_value,
       ROUND(AVG(CASE WHEN status = 'SUCCESS' THEN processing_seconds END), 2) AS avg_success_seconds,
       RANK() OVER (ORDER BY SUM(status = 'SUCCESS') / COUNT(*) DESC)  AS reliability_rank
FROM   vw_transactions_clean
GROUP  BY payment_method
ORDER  BY reliability_rank;

-- 4.5 GATEWAY x PAYMENT METHOD  (which combination is the weakest?)
-- 4.5a Ranked list (non-success = FAILED + PENDING)
SELECT gateway_name, payment_method,
       COUNT(*)                                                    AS txns,
       SUM(status = 'FAILED')                                      AS failed,
       SUM(status = 'PENDING')                                     AS pending,
       ROUND(100 * SUM(status = 'FAILED')  / COUNT(*), 2)          AS failure_rate_pct,
       ROUND(100 * SUM(status <> 'SUCCESS') / COUNT(*), 2)         AS non_success_rate_pct,
       RANK() OVER (ORDER BY SUM(status <> 'SUCCESS') / COUNT(*) DESC) AS worst_rank
FROM   vw_transactions_clean
GROUP  BY gateway_name, payment_method
ORDER  BY worst_rank;

-- 4.5b Heat-map layout: failure rate % (rows = method, columns = gateway)
SELECT payment_method,
       ROUND(100 * SUM(gateway_name = 'Razorpay' AND status = 'FAILED') / SUM(gateway_name = 'Razorpay'), 2) AS Razorpay_failure_pct,
       ROUND(100 * SUM(gateway_name = 'Cashfree' AND status = 'FAILED') / SUM(gateway_name = 'Cashfree'), 2) AS Cashfree_failure_pct,
       ROUND(100 * SUM(gateway_name = 'PayU'     AND status = 'FAILED') / SUM(gateway_name = 'PayU'),     2) AS PayU_failure_pct
FROM   vw_transactions_clean
GROUP  BY payment_method
ORDER  BY payment_method;


-- 4.6 ERROR CODE ANALYSIS  (why do payments fail?)
-- 4.6a Error codes ranked by volume
SELECT error_code, failure_category,
       COUNT(*)                                                    AS txns,
       ROUND(100 * COUNT(*) /
             (SELECT COUNT(*) FROM vw_transactions_clean WHERE error_code IS NOT NULL), 2) AS pct_of_all_errors,
       SUM(status = 'FAILED')                                      AS failed,
       SUM(status = 'PENDING')                                     AS pending,
       ROUND(SUM(amount), 2)                                       AS value_affected,
       ROUND(AVG(amount), 2)                                       AS avg_amount
FROM   vw_transactions_clean
WHERE  error_code IS NOT NULL
GROUP  BY error_code, failure_category
ORDER  BY txns DESC;

-- 4.6b Who can fix it?  (Technical = the company / gateway can fix)
SELECT failure_category,
       COUNT(*)                                                    AS txns,
       ROUND(100 * COUNT(*) /
             (SELECT COUNT(*) FROM vw_transactions_clean WHERE error_code IS NOT NULL), 2) AS pct_of_all_errors,
       ROUND(SUM(amount), 2)                                       AS value_affected
FROM   vw_transactions_clean
WHERE  error_code IS NOT NULL
GROUP  BY failure_category
ORDER  BY txns DESC;

-- 4.6c Error code by gateway (counts)
SELECT error_code,
       SUM(gateway_name = 'Razorpay') AS Razorpay,
       SUM(gateway_name = 'Cashfree') AS Cashfree,
       SUM(gateway_name = 'PayU')     AS PayU,
       COUNT(*)                       AS total
FROM   vw_transactions_clean
WHERE  error_code IS NOT NULL
GROUP  BY error_code
ORDER  BY total DESC;

-- 4.6d Error code by payment method (counts)
SELECT error_code,
       SUM(payment_method = 'UPI')         AS UPI,
       SUM(payment_method = 'Credit Card') AS Credit_Card,
       SUM(payment_method = 'Debit Card')  AS Debit_Card,
       SUM(payment_method = 'NetBanking')  AS NetBanking,
       SUM(payment_method = 'Wallet')      AS Wallet,
       COUNT(*)                            AS total
FROM   vw_transactions_clean
WHERE  error_code IS NOT NULL
GROUP  BY error_code
ORDER  BY total DESC;

-- 4.7 WHEN DO FAILURES HAPPEN?  Hour of day
-- 4.7a Failure rate for each hour
SELECT txn_hour,
       CASE WHEN txn_hour BETWEEN 0  AND 5  THEN '1 Night (00-05)'
            WHEN txn_hour BETWEEN 6  AND 11 THEN '2 Morning (06-11)'
            WHEN txn_hour BETWEEN 12 AND 17 THEN '3 Afternoon (12-17)'
            ELSE                                 '4 Evening (18-23)' END AS time_band,
       COUNT(*)                                                    AS txns,
       SUM(status = 'FAILED')                                      AS failed,
       ROUND(100 * SUM(status = 'FAILED')  / COUNT(*), 2)          AS failure_rate_pct,
       ROUND(100 * SUM(status = 'PENDING') / COUNT(*), 2)          AS pending_rate_pct,
       RANK() OVER (ORDER BY SUM(status = 'FAILED') / COUNT(*) DESC) AS failure_rank
FROM   vw_transactions_clean
GROUP  BY txn_hour
ORDER  BY txn_hour;

-- 4.7b Time-band summary
SELECT time_band, COUNT(*) AS txns, SUM(status = 'FAILED') AS failed,
       ROUND(100 * SUM(status = 'FAILED')  / COUNT(*), 2) AS failure_rate_pct,
       ROUND(100 * SUM(status = 'PENDING') / COUNT(*), 2) AS pending_rate_pct
FROM  (SELECT status,
              CASE WHEN txn_hour BETWEEN 0  AND 5  THEN '1 Night (00-05)'
                   WHEN txn_hour BETWEEN 6  AND 11 THEN '2 Morning (06-11)'
                   WHEN txn_hour BETWEEN 12 AND 17 THEN '3 Afternoon (12-17)'
                   ELSE                                 '4 Evening (18-23)' END AS time_band
       FROM   vw_transactions_clean) x
GROUP  BY time_band
ORDER  BY time_band;

-- 4.7c The 5 worst hours for failures
SELECT txn_hour, txns, failed, failure_rate_pct
FROM  (SELECT txn_hour, COUNT(*) AS txns, SUM(status = 'FAILED') AS failed,
              ROUND(100 * SUM(status = 'FAILED') / COUNT(*), 2) AS failure_rate_pct,
              RANK() OVER (ORDER BY SUM(status = 'FAILED') / COUNT(*) DESC) AS rk
       FROM   vw_transactions_clean GROUP BY txn_hour) h
WHERE  rk <= 5
ORDER  BY rk;

-- 4.8 DAY OF WEEK
SELECT WEEKDAY(txn_date) + 1                                       AS day_no,
       txn_day,
       COUNT(*)                                                    AS txns,
       SUM(status = 'FAILED')                                      AS failed,
       ROUND(100 * SUM(status = 'FAILED')  / COUNT(*), 2)          AS failure_rate_pct,
       ROUND(100 * SUM(status = 'PENDING') / COUNT(*), 2)          AS pending_rate_pct
FROM   vw_transactions_clean
GROUP  BY day_no, txn_day
ORDER  BY day_no;

-- 4.9 TICKET SIZE  (do big payments fail more?)
-- 4.9a Failure rate by amount band
SELECT amount_band,
       COUNT(*)                                                    AS txns,
       SUM(status = 'FAILED')                                      AS failed,
       ROUND(100 * SUM(status = 'FAILED')  / COUNT(*), 2)          AS failure_rate_pct,
       ROUND(100 * SUM(status = 'PENDING') / COUNT(*), 2)          AS pending_rate_pct,
       ROUND(SUM(CASE WHEN status = 'FAILED' THEN amount ELSE 0 END), 2) AS failed_value
FROM   vw_transactions_clean
GROUP  BY FLOOR(amount / 5000), amount_band
ORDER  BY FLOOR(amount / 5000);

-- 4.9b The 10 largest failed payments
SELECT transaction_id, customer_id, payment_method, gateway_name, amount, error_code, created_at
FROM   vw_transactions_clean
WHERE  status = 'FAILED'
ORDER  BY amount DESC
LIMIT  10;

-- 4.10 PROCESSING TIME  (seconds from created_at to updated_at)
-- 4.10a By outcome
SELECT status, COUNT(*) AS txns,
       MIN(processing_seconds)              AS min_sec,
       ROUND(AVG(processing_seconds), 2)    AS avg_sec,
       MAX(processing_seconds)              AS max_sec
FROM   vw_transactions_clean
GROUP  BY status;

-- 4.10b Speed of SUCCESSFUL payments by gateway (p50 / p90 percentiles)
WITH r AS (
    SELECT gateway_name, processing_seconds,
           ROW_NUMBER() OVER (PARTITION BY gateway_name ORDER BY processing_seconds) AS rn,
           COUNT(*)     OVER (PARTITION BY gateway_name)                             AS cnt
    FROM   vw_transactions_clean
    WHERE  status = 'SUCCESS'
)
SELECT gateway_name,
       COUNT(*)                                                AS successful_txns,
       ROUND(AVG(processing_seconds), 2)                       AS avg_sec,
       MAX(CASE WHEN rn <= CEIL(0.50 * cnt) THEN processing_seconds END) AS p50_sec,
       MAX(CASE WHEN rn <= CEIL(0.90 * cnt) THEN processing_seconds END) AS p90_sec,
       MAX(processing_seconds)                                 AS max_sec
FROM   r
GROUP  BY gateway_name
ORDER  BY avg_sec;

-- 4.11 CUSTOMER IMPACT
-- 4.11a Customers hit by the most failures
SELECT customer_id,
       COUNT(*)                                            AS txns,
       SUM(status = 'FAILED')                              AS failed,
       ROUND(100 * SUM(status = 'FAILED') / COUNT(*), 2)   AS failure_rate_pct,
       ROUND(SUM(CASE WHEN status = 'FAILED' THEN amount ELSE 0 END), 2) AS failed_value
FROM   vw_transactions_clean
GROUP  BY customer_id
ORDER  BY failed DESC, failure_rate_pct DESC
LIMIT  10;

-- 4.11b How many customers experienced N failures?
WITH c AS (SELECT customer_id, SUM(status = 'FAILED') AS failed
           FROM vw_transactions_clean GROUP BY customer_id)
SELECT failed AS failed_txns_per_customer, COUNT(*) AS customers,
       ROUND(100 * COUNT(*) / (SELECT COUNT(*) FROM c), 2) AS pct_of_customers
FROM   c
GROUP  BY failed
ORDER  BY failed;

-- 4.11c What does a customer's NEXT attempt look like after each outcome?
--       (Shows whether a failure/pending payment pushes people to fail again.)
WITH s AS (
    SELECT customer_id, status,
           LEAD(status) OVER (PARTITION BY customer_id ORDER BY created_at, transaction_id) AS next_status
    FROM   vw_transactions_clean
)
SELECT status AS this_attempt, next_status AS next_attempt, COUNT(*) AS cases,
       ROUND(100 * COUNT(*) / SUM(COUNT(*)) OVER (PARTITION BY status), 2) AS pct_of_this_outcome
FROM   s
WHERE  next_status IS NOT NULL
GROUP  BY status, next_status
ORDER  BY status, next_status;

-- 4.12 REVENUE LEAKAGE  (what failures cost, net of retry recovery)
SELECT 'Gateway' AS dimension, gateway_name AS segment,
       ROUND(SUM(amount), 2)                                                  AS gross_attempted,
       ROUND(SUM(CASE WHEN status = 'SUCCESS' THEN amount ELSE 0 END), 2)     AS successful_value,
       ROUND(SUM(CASE WHEN status = 'FAILED'  THEN amount ELSE 0 END), 2)     AS failed_value,
       ROUND(SUM(CASE WHEN status = 'PENDING' THEN amount ELSE 0 END), 2)     AS pending_value,
       ROUND(SUM(recovered_amount), 2)                                        AS recovered_by_retry,
       ROUND(SUM(CASE WHEN status IN ('FAILED','PENDING') THEN amount ELSE 0 END)
             - SUM(recovered_amount), 2)                                      AS net_revenue_at_risk,
       ROUND(100 * (SUM(CASE WHEN status IN ('FAILED','PENDING') THEN amount ELSE 0 END)
             - SUM(recovered_amount)) / SUM(amount), 2)                       AS at_risk_pct_of_attempted
FROM   vw_transactions_clean
GROUP  BY gateway_name
UNION ALL
SELECT 'Payment method', payment_method,
       ROUND(SUM(amount), 2),
       ROUND(SUM(CASE WHEN status = 'SUCCESS' THEN amount ELSE 0 END), 2),
       ROUND(SUM(CASE WHEN status = 'FAILED'  THEN amount ELSE 0 END), 2),
       ROUND(SUM(CASE WHEN status = 'PENDING' THEN amount ELSE 0 END), 2),
       ROUND(SUM(recovered_amount), 2),
       ROUND(SUM(CASE WHEN status IN ('FAILED','PENDING') THEN amount ELSE 0 END)
             - SUM(recovered_amount), 2),
       ROUND(100 * (SUM(CASE WHEN status IN ('FAILED','PENDING') THEN amount ELSE 0 END)
             - SUM(recovered_amount)) / SUM(amount), 2)
FROM   vw_transactions_clean
GROUP  BY payment_method
ORDER  BY dimension, net_revenue_at_risk DESC;

-- 4.13 GATEWAY RELIABILITY SCORECARD  (rank 1 = best on each measure)
WITH g AS (
    SELECT gateway_name,
           SUM(status = 'SUCCESS') / COUNT(*)                                AS sr,
           SUM(status = 'FAILED')  / COUNT(*)                                AS fr,
           SUM(status = 'PENDING') / COUNT(*)                                AS pr,
           AVG(CASE WHEN status = 'SUCCESS' THEN processing_seconds END)     AS lat
    FROM   vw_transactions_clean
    GROUP  BY gateway_name
), r AS (
    SELECT gateway_name,
           ROUND(100 * sr, 2) AS success_rate_pct,
           ROUND(100 * fr, 2) AS failure_rate_pct,
           ROUND(100 * pr, 2) AS pending_rate_pct,
           ROUND(lat, 2)      AS avg_success_seconds,
           RANK() OVER (ORDER BY sr DESC) AS rank_success,
           RANK() OVER (ORDER BY fr)      AS rank_failure,
           RANK() OVER (ORDER BY pr)      AS rank_pending,
           RANK() OVER (ORDER BY lat)     AS rank_speed
    FROM   g
)
SELECT r.*,
       ROUND((rank_success + rank_failure + rank_pending + rank_speed) / 4, 2)           AS avg_rank,
       RANK() OVER (ORDER BY rank_success + rank_failure + rank_pending + rank_speed)    AS overall_rank
FROM   r
ORDER  BY overall_rank;

-- PART 5A | NEW FEATURE 1  -  RETRY RECOVERY ANALYSIS   (high priority)
CREATE OR REPLACE VIEW vw_retry_recovery AS
SELECT  c.transaction_id,
        c.customer_id,
        c.payment_method,
        c.gateway_name,
        c.error_code,
        c.failure_category,
        c.amount,
        c.created_at,
        c.txn_month,
        c.txn_hour,
        r.retry_id,
        r.attempt_number,
        r.retry_status,
        r.time_diff_minutes                                          AS minutes_to_retry,
        CASE WHEN r.retry_id IS NULL THEN 0 ELSE 1 END               AS was_retried,
        CASE WHEN r.retry_status = 'SUCCESS' THEN 1 ELSE 0 END       AS was_recovered,
        CASE WHEN r.retry_status = 'SUCCESS' THEN r.recovered_amount ELSE 0 END AS recovered_amount,
        c.amount - CASE WHEN r.retry_status = 'SUCCESS' THEN r.recovered_amount ELSE 0 END AS unrecovered_amount
FROM    vw_transactions_clean c
LEFT JOIN payment_retries r ON r.original_transaction_id = c.transaction_id
WHERE   c.status = 'FAILED';

-- 5A.1 Headline: how much do retries recover?
SELECT COUNT(*)                                                       AS failed_txns,
       SUM(was_retried)                                               AS retried_txns,
       ROUND(100 * SUM(was_retried)   / COUNT(*), 2)                  AS retry_coverage_pct,
       SUM(was_recovered)                                             AS recovered_txns,
       ROUND(100 * SUM(was_recovered) / COUNT(*), 2)                  AS recovery_rate_pct,
       ROUND(100 * SUM(was_recovered) / NULLIF(SUM(was_retried), 0), 2) AS retry_success_pct,
       ROUND(SUM(amount), 2)                                          AS failed_value,
       ROUND(SUM(recovered_amount), 2)                                AS recovered_revenue,
       ROUND(SUM(unrecovered_amount), 2)                              AS unrecovered_value,
       ROUND(100 * SUM(recovered_amount) / SUM(amount), 2)            AS value_recovery_pct
FROM   vw_retry_recovery;

-- 5A.2 Effect on the overall success rate (before vs after retries)
SELECT COUNT(*)                                                                  AS total_txns,
       ROUND(100 * SUM(status = 'SUCCESS') / COUNT(*), 2)                        AS success_rate_before_retries_pct,
       ROUND(100 * SUM(final_status IN ('SUCCESS','RECOVERED')) / COUNT(*), 2)   AS success_rate_after_retries_pct,
       ROUND(100 * SUM(final_status IN ('SUCCESS','RECOVERED')) / COUNT(*)
             - 100 * SUM(status = 'SUCCESS') / COUNT(*), 2)                      AS uplift_pp
FROM   vw_transactions_clean;

-- 5A.3 Which PAYMENT METHOD recovers best?
SELECT payment_method,
       COUNT(*)                                                    AS failed_txns,
       SUM(was_retried)                                            AS retried,
       SUM(was_recovered)                                          AS recovered,
       ROUND(100 * SUM(was_recovered) / COUNT(*), 2)               AS recovery_rate_pct,
       ROUND(SUM(recovered_amount), 2)                             AS recovered_revenue,
       ROUND(SUM(unrecovered_amount), 2)                           AS unrecovered_value,
       RANK() OVER (ORDER BY SUM(was_recovered) / COUNT(*) DESC)   AS recovery_rank
FROM   vw_retry_recovery
GROUP  BY payment_method
ORDER  BY recovery_rank;

-- 5A.4 Which GATEWAY recovers best?
SELECT gateway_name,
       COUNT(*)                                                    AS failed_txns,
       SUM(was_retried)                                            AS retried,
       SUM(was_recovered)                                          AS recovered,
       ROUND(100 * SUM(was_recovered) / COUNT(*), 2)               AS recovery_rate_pct,
       ROUND(SUM(recovered_amount), 2)                             AS recovered_revenue,
       ROUND(SUM(unrecovered_amount), 2)                           AS unrecovered_value,
       RANK() OVER (ORDER BY SUM(was_recovered) / COUNT(*) DESC)   AS recovery_rank
FROM   vw_retry_recovery
GROUP  BY gateway_name
ORDER  BY recovery_rank;

-- 5A.5 Which FAILURE REASON recovers best?  (retry coverage per error code)
SELECT error_code, failure_category,
       COUNT(*)                                                    AS failed_txns,
       SUM(was_recovered)                                          AS recovered,
       ROUND(100 * SUM(was_recovered) / COUNT(*), 2)               AS recovery_rate_pct,
       ROUND(SUM(recovered_amount), 2)                             AS recovered_revenue,
       ROUND(SUM(unrecovered_amount), 2)                           AS unrecovered_value
FROM   vw_retry_recovery
GROUP  BY error_code, failure_category
ORDER  BY recovery_rate_pct DESC;

-- 5A.6 Gateway x payment method recovery matrix
SELECT gateway_name, payment_method,
       COUNT(*)                                                    AS failed_txns,
       SUM(was_recovered)                                          AS recovered,
       ROUND(100 * SUM(was_recovered) / COUNT(*), 2)               AS recovery_rate_pct,
       ROUND(SUM(recovered_amount), 2)                             AS recovered_revenue,
       RANK() OVER (ORDER BY SUM(was_recovered) / COUNT(*) DESC)   AS recovery_rank
FROM   vw_retry_recovery
GROUP  BY gateway_name, payment_method
ORDER  BY recovery_rank;

-- 5A.7 How quickly do customers retry successfully?
SELECT CASE WHEN minutes_to_retry <= 15 THEN '1) 0-15 min'
            WHEN minutes_to_retry <= 30 THEN '2) 16-30 min'
            WHEN minutes_to_retry <= 45 THEN '3) 31-45 min'
            ELSE                             '4) 46-60 min' END     AS retry_delay_band,
       COUNT(*)                                                     AS recovered_txns,
       ROUND(100 * COUNT(*) / SUM(COUNT(*)) OVER (), 2)             AS pct_of_recoveries,
       ROUND(SUM(recovered_amount), 2)                              AS recovered_revenue,
       ROUND(AVG(minutes_to_retry), 1)                              AS avg_minutes
FROM   vw_retry_recovery
WHERE  was_recovered = 1
GROUP  BY retry_delay_band
ORDER  BY retry_delay_band;

-- 5A.8 Monthly recovered revenue trend
SELECT txn_month,
       COUNT(*)                                                    AS failed_txns,
       SUM(was_recovered)                                          AS recovered,
       ROUND(100 * SUM(was_recovered) / COUNT(*), 2)               AS recovery_rate_pct,
       ROUND(SUM(recovered_amount), 2)                             AS recovered_revenue,
       ROUND(SUM(unrecovered_amount), 2)                           AS unrecovered_value
FROM   vw_retry_recovery
GROUP  BY txn_month
ORDER  BY txn_month;

-- 5A.9 MISSED OPPORTUNITY: failed payments that were never retried
SELECT failure_category,
       COUNT(*)                                                    AS never_retried_txns,
       ROUND(SUM(amount), 2)                                       AS value_never_retried,
       ROUND(AVG(amount), 2)                                       AS avg_amount
FROM   vw_retry_recovery
WHERE  was_retried = 0
GROUP  BY failure_category
ORDER  BY value_never_retried DESC;

-- 5A.10 The 15 biggest un-retried failed payments (call-back / auto-retry list)
SELECT transaction_id, customer_id, payment_method, gateway_name, error_code, amount, created_at
FROM   vw_retry_recovery
WHERE  was_retried = 0
ORDER  BY amount DESC
LIMIT  15;

-- PART 5B | NEW FEATURE 2  -  PENDING PAYMENT MONITORING
CREATE OR REPLACE VIEW vw_pending_monitor AS
-- Two clocks are kept for every PENDING payment:
--   pending_minutes          = OBSERVED pending time (gateway's last status update - created_at)
--   age_minutes_at_snapshot  = ELAPSED time since initiation, still unresolved at the data snapshot
--                              TIMESTAMPDIFF(MINUTE, created_at, COALESCE(resolved_at, snapshot))
--                              A PENDING row has no final resolution, so its clock runs to the snapshot
--                              (the snapshot plays the role of NOW() for a historical dataset).
SELECT  x.*,
        CASE WHEN x.age_minutes_at_snapshot > 5  THEN 1 ELSE 0 END             AS age_over_5_min,
        CASE WHEN x.age_minutes_at_snapshot > 15 THEN 1 ELSE 0 END             AS age_over_15_min,
        CASE WHEN x.age_minutes_at_snapshot > 30 THEN 1 ELSE 0 END             AS age_over_30_min,
        CASE WHEN x.age_minutes_at_snapshot > 30 THEN 'ACTION REQUIRED (>30 min)'
             WHEN x.age_minutes_at_snapshot > 15 THEN 'CRITICAL (>15 min)'
             WHEN x.age_minutes_at_snapshot > 5  THEN 'WARNING (>5 min)'
             ELSE 'OK (<=5 min)' END                                           AS severity_at_snapshot
FROM (
    SELECT  c.transaction_id,
            c.customer_id,
            c.payment_method,
            c.gateway_name,
            c.amount,
            c.error_code,
            c.created_at,
            c.updated_at,
            c.txn_hour,
            ROUND(TIMESTAMPDIFF(SECOND, c.created_at, c.updated_at) / 60, 1)       AS pending_minutes,
            CASE WHEN TIMESTAMPDIFF(SECOND, c.created_at, c.updated_at) > 300  THEN 1 ELSE 0 END AS over_5_min,
            CASE WHEN TIMESTAMPDIFF(SECOND, c.created_at, c.updated_at) > 900  THEN 1 ELSE 0 END AS over_15_min,
            CASE WHEN TIMESTAMPDIFF(SECOND, c.created_at, c.updated_at) > 1800 THEN 1 ELSE 0 END AS over_30_min,
            CASE WHEN TIMESTAMPDIFF(SECOND, c.created_at, c.updated_at) > 1800 THEN 'ACTION REQUIRED (>30 min)'
                 WHEN TIMESTAMPDIFF(SECOND, c.created_at, c.updated_at) > 900  THEN 'CRITICAL (>15 min)'
                 WHEN TIMESTAMPDIFF(SECOND, c.created_at, c.updated_at) > 300  THEN 'WARNING (>5 min)'
                 ELSE 'OK (<=5 min)' END                                           AS severity,
            s.as_of                                                                AS snapshot_time,
            TIMESTAMPDIFF(MINUTE, c.created_at,
                          COALESCE(CASE WHEN c.status <> 'PENDING' THEN c.updated_at END, s.as_of)) AS age_minutes_at_snapshot,
            TIMESTAMPDIFF(HOUR, c.created_at, s.as_of)                             AS unresolved_hours_at_snapshot,
            TIMESTAMPDIFF(DAY,  c.created_at, s.as_of)                             AS unresolved_days_at_snapshot,
            -- customer paid again successfully within 24h => possible double debit / duplicate payment
            CASE WHEN EXISTS (SELECT 1 FROM transactions n
                              WHERE  n.customer_id = c.customer_id
                                AND  n.status      = 'SUCCESS'
                                AND  n.created_at  > c.created_at
                                AND  n.created_at <= c.created_at + INTERVAL 24 HOUR)
                 THEN 1 ELSE 0 END                                                 AS paid_again_within_24h
    FROM    vw_transactions_clean c
    CROSS JOIN vw_data_snapshot s
    WHERE   c.status = 'PENDING'
) x;

-- 5B.1 Threshold monitor on OBSERVED pending time (last gateway update - created_at): beyond 5 / 15 / 30 minutes?
SELECT t.threshold_min,
       COUNT(p.transaction_id)                                             AS pending_txns_over_threshold,
       ROUND(100 * COUNT(p.transaction_id) / (SELECT COUNT(*) FROM vw_pending_monitor), 2) AS pct_of_pending,
       ROUND(IFNULL(SUM(p.amount), 0), 2)                                  AS value_stuck
FROM  (SELECT 5 AS threshold_min UNION ALL SELECT 15 UNION ALL SELECT 30) t
LEFT JOIN vw_pending_monitor p ON p.pending_minutes > t.threshold_min
GROUP BY t.threshold_min
ORDER BY t.threshold_min;

-- 5B.2 Pending time bands (each payment counted once)
SELECT pending_band,
       COUNT(*)                                                    AS pending_txns,
       ROUND(100 * COUNT(*) / SUM(COUNT(*)) OVER (), 2)            AS pct_of_pending,
       ROUND(SUM(amount), 2)                                       AS value_stuck
FROM  (SELECT amount,
              CASE WHEN pending_minutes <= 5  THEN '1) 0-5 min'
                   WHEN pending_minutes <= 15 THEN '2) 5-15 min'
                   WHEN pending_minutes <= 30 THEN '3) 15-30 min'
                   ELSE                            '4) over 30 min' END AS pending_band
       FROM   vw_pending_monitor) x
GROUP  BY pending_band
ORDER  BY pending_band;

-- 5B.3 Severity by gateway
WITH tot AS (SELECT gateway_name, COUNT(*) AS all_txns FROM transactions GROUP BY gateway_name)
SELECT p.gateway_name,
       COUNT(*)                                                    AS pending_txns,
       ROUND(100 * COUNT(*) / MAX(t.all_txns), 2)                  AS pending_rate_pct,
       SUM(p.over_5_min = 1  AND p.over_15_min = 0)                AS warning_5_15,
       SUM(p.over_15_min = 1 AND p.over_30_min = 0)                AS critical_15_30,
       SUM(p.over_30_min = 1)                                      AS action_required_over_30,
       ROUND(AVG(p.pending_minutes), 1)                            AS avg_pending_min,
       ROUND(SUM(p.amount), 2)                                     AS value_stuck,
       ROUND(SUM(CASE WHEN p.over_30_min = 1 THEN p.amount ELSE 0 END), 2) AS value_stuck_over_30
FROM   vw_pending_monitor p
JOIN   tot t ON t.gateway_name = p.gateway_name
GROUP  BY p.gateway_name
ORDER  BY action_required_over_30 DESC;

-- 5B.4 Severity by payment method
WITH tot AS (SELECT payment_method, COUNT(*) AS all_txns FROM transactions GROUP BY payment_method)
SELECT p.payment_method,
       COUNT(*)                                                    AS pending_txns,
       ROUND(100 * COUNT(*) / MAX(t.all_txns), 2)                  AS pending_rate_pct,
       SUM(p.over_5_min = 1  AND p.over_15_min = 0)                AS warning_5_15,
       SUM(p.over_15_min = 1 AND p.over_30_min = 0)                AS critical_15_30,
       SUM(p.over_30_min = 1)                                      AS action_required_over_30,
       ROUND(AVG(p.pending_minutes), 1)                            AS avg_pending_min,
       ROUND(SUM(p.amount), 2)                                     AS value_stuck
FROM   vw_pending_monitor p
JOIN   tot t ON t.payment_method = p.payment_method
GROUP  BY p.payment_method
ORDER  BY action_required_over_30 DESC;

-- 5B.5 Gateway x payment method hot-spots (share of that segment that is pending > 15 min)
SELECT c.gateway_name, c.payment_method,
       COUNT(*)                                                    AS txns,
       SUM(c.status = 'PENDING')                                   AS pending_txns,
       SUM(c.status = 'PENDING' AND c.processing_seconds > 900)    AS pending_over_15_min,
       ROUND(100 * SUM(c.status = 'PENDING' AND c.processing_seconds > 900) / COUNT(*), 2) AS pct_pending_over_15_min,
       RANK() OVER (ORDER BY SUM(c.status = 'PENDING' AND c.processing_seconds > 900) / COUNT(*) DESC) AS hotspot_rank
FROM   vw_transactions_clean c
GROUP  BY c.gateway_name, c.payment_method
ORDER  BY hotspot_rank;

-- 5B.6 When do payments go pending?  (by hour)
SELECT txn_hour,
       COUNT(*)                                                    AS txns,
       SUM(status = 'PENDING')                                     AS pending_txns,
       ROUND(100 * SUM(status = 'PENDING') / COUNT(*), 2)          AS pending_rate_pct,
       SUM(status = 'PENDING' AND processing_seconds > 900)        AS pending_over_15_min,
       SUM(status = 'PENDING' AND processing_seconds > 1800)       AS pending_over_30_min
FROM   vw_transactions_clean
GROUP  BY txn_hour
ORDER  BY txn_hour;

-- 5B.7 Snapshot check: no pending payment ever moved to a final status.
SELECT CASE WHEN unresolved_hours_at_snapshot < 24      THEN '1) under 1 day'
            WHEN unresolved_hours_at_snapshot < 24 * 7  THEN '2) 1-7 days'
            WHEN unresolved_hours_at_snapshot < 24 * 30 THEN '3) 7-30 days'
            ELSE                                             '4) over 30 days' END AS unresolved_age,
       COUNT(*)                                                    AS pending_txns,
       ROUND(SUM(amount), 2)                                       AS value_stuck
FROM   vw_pending_monitor
GROUP  BY unresolved_age
ORDER  BY unresolved_age;

-- 5B.8 Double-debit risk: customer paid again successfully within 24h of a pending payment
SELECT gateway_name,
       COUNT(*)                                                    AS pending_txns,
       SUM(paid_again_within_24h)                                  AS customer_paid_again,
       ROUND(100 * SUM(paid_again_within_24h) / COUNT(*), 2)       AS pct_paid_again,
       ROUND(SUM(CASE WHEN paid_again_within_24h = 1 THEN amount ELSE 0 END), 2) AS value_at_double_debit_risk
FROM   vw_pending_monitor
GROUP  BY gateway_name
ORDER  BY customer_paid_again DESC;

-- 5B.9 Investigation work-list: the 25 most urgent pending payments
SELECT transaction_id, customer_id, payment_method, gateway_name, amount,
       created_at, pending_minutes, severity, paid_again_within_24h
FROM   vw_pending_monitor
ORDER  BY pending_minutes DESC, amount DESC
LIMIT  25;

-- 5B.10 Snapshot-age monitor: elapsed time since initiation for payments STILL PENDING at the snapshot
--        (5 / 15 / 30-minute tiers on age_minutes_at_snapshot, i.e. TIMESTAMPDIFF(created_at -> COALESCE(resolved, snapshot)))
SELECT t.threshold_min,
       CASE t.threshold_min WHEN 5 THEN 'WARNING' WHEN 15 THEN 'CRITICAL' ELSE 'ACTION REQUIRED' END AS tier,
       COUNT(p.transaction_id)                                             AS pending_txns_over_threshold,
       ROUND(100 * COUNT(p.transaction_id) / (SELECT COUNT(*) FROM vw_pending_monitor), 2) AS pct_of_pending,
       ROUND(IFNULL(SUM(p.amount), 0), 2)                                  AS value_stuck
FROM  (SELECT 5 AS threshold_min UNION ALL SELECT 15 UNION ALL SELECT 30) t
LEFT JOIN vw_pending_monitor p ON p.age_minutes_at_snapshot > t.threshold_min
GROUP BY t.threshold_min
ORDER BY t.threshold_min;

-- 5B.11 Where are the bottlenecks? Unresolved pending payments by gateway x payment method
SELECT gateway_name, payment_method,
       COUNT(*)                                                    AS pending_txns,
       SUM(age_over_30_min)                                        AS action_required_over_30,
       SUM(paid_again_within_24h)                                  AS customer_paid_again,
       ROUND(SUM(amount), 2)                                       AS value_stuck,
       ROUND(AVG(age_minutes_at_snapshot) / 1440, 1)               AS avg_age_days_at_snapshot
FROM   vw_pending_monitor
GROUP  BY gateway_name, payment_method
ORDER  BY value_stuck DESC;

-- 5B.12 Escalation work-list ranked by snapshot age (double-debit risks first)
SELECT transaction_id, customer_id, payment_method, gateway_name, amount, created_at,
       pending_minutes,
       ROUND(age_minutes_at_snapshot / 1440, 1)                    AS age_days_at_snapshot,
       severity_at_snapshot, paid_again_within_24h
FROM   vw_pending_monitor
ORDER  BY paid_again_within_24h DESC, age_minutes_at_snapshot DESC, amount DESC
LIMIT  25;

-- PART 5C | NEW FEATURE 3  -  REFUND & SETTLEMENT RECONCILIATION
CREATE OR REPLACE VIEW vw_refund_reconciliation AS
-- business_days_open = Mon-Fri days elapsed between the refund request and the snapshot
--                      (request day excluded, weekends excluded, public holidays ignored).
-- Open refunds (not COMPLETED) older than 5 business days are STUCK, 3-5 business days AT RISK.
-- was_capped_in_cleaning: cleaning step 5.2 caps refund_amount at the payment amount, so the
--                      ORIGINAL amount is read back from refunds_settlements_backup to keep
--                      the "refund exceeds payment" exception visible.
SELECT  y.*,
        CASE WHEN y.recon_status LIKE 'MISMATCH%' OR y.recon_status LIKE 'AGED%'
               OR y.recon_status LIKE 'STUCK%'
             THEN 1 ELSE 0 END                                                AS needs_investigation
FROM (
    SELECT  z.*,
            CASE
                WHEN z.was_capped_in_cleaning = 1                                      THEN 'MISMATCH: refund exceeded payment (capped in cleaning)'
                WHEN z.refund_amount > z.txn_amount                                    THEN 'MISMATCH: refund exceeds payment'
                WHEN z.txn_status <> 'SUCCESS'                                         THEN 'MISMATCH: refund on non-successful payment'
                WHEN z.requested_at < z.txn_created_at                                 THEN 'MISMATCH: refund before payment'
                WHEN z.refund_status = 'COMPLETED' AND z.settlement_status <> 'SETTLED' THEN 'MISMATCH: completed but not settled'
                WHEN z.refund_status <> 'COMPLETED' AND z.settlement_status = 'SETTLED' THEN 'MISMATCH: settled but refund not completed'
                WHEN z.settlement_status = 'SETTLED' AND z.settlement_id IS NULL       THEN 'MISMATCH: settled without settlement id'
                WHEN z.refund_status = 'COMPLETED'                                     THEN 'RECONCILED'
                WHEN z.refund_age_days > 30                                            THEN 'AGED: open over 30 days'
                WHEN z.business_days_open > 5                                          THEN 'STUCK: open over 5 business days'
                WHEN z.business_days_open >= 3                                         THEN 'AT RISK: open 3-5 business days'
                ELSE 'IN PROGRESS: open under 3 business days'
            END                                                               AS recon_status
    FROM (
        SELECT  f.refund_id,
                f.transaction_id,
                c.customer_id,
                c.payment_method,
                c.gateway_name,
                c.status                                                          AS txn_status,
                c.amount                                                          AS txn_amount,
                c.created_at                                                      AS txn_created_at,
                f.refund_amount,
                b.refund_amount                                                   AS refund_amount_as_requested,
                CASE WHEN b.refund_amount > f.refund_amount + 0.01 THEN 1 ELSE 0 END AS was_capped_in_cleaning,
                f.refund_status,
                f.settlement_id,
                f.settlement_status,
                f.requested_at,
                DATE_FORMAT(f.requested_at, '%Y-%m')                              AS refund_month,
                TIMESTAMPDIFF(HOUR, c.created_at, f.requested_at)                 AS hours_payment_to_refund,
                s.as_of                                                           AS snapshot_time,
                DATEDIFF(s.as_of, f.requested_at)                                 AS refund_age_days,
                DATEDIFF(DATE(s.as_of), DATE(f.requested_at))
                  - ( 2 * ((WEEKDAY(f.requested_at) + DATEDIFF(DATE(s.as_of), DATE(f.requested_at))) DIV 7)
                      + GREATEST(MOD(WEEKDAY(f.requested_at) + DATEDIFF(DATE(s.as_of), DATE(f.requested_at)), 7) - 4, 0)
                      - GREATEST(WEEKDAY(f.requested_at) - 4, 0) )                AS business_days_open,
                CASE WHEN DATEDIFF(s.as_of, f.requested_at) <= 7  THEN '1) 0-7 days'
                     WHEN DATEDIFF(s.as_of, f.requested_at) <= 14 THEN '2) 8-14 days'
                     WHEN DATEDIFF(s.as_of, f.requested_at) <= 30 THEN '3) 15-30 days'
                     WHEN DATEDIFF(s.as_of, f.requested_at) <= 60 THEN '4) 31-60 days'
                     ELSE '5) over 60 days' END                                   AS age_bucket,
                CASE WHEN f.refund_status = 'COMPLETED' THEN f.refund_amount ELSE 0 END    AS completed_amount,
                CASE WHEN f.settlement_status = 'UNSETTLED' THEN f.refund_amount ELSE 0 END AS unsettled_amount
        FROM    refunds_settlements f
        JOIN    vw_transactions_clean c ON c.transaction_id = f.transaction_id
        LEFT JOIN refunds_settlements_backup b ON b.refund_id = f.refund_id
        CROSS JOIN vw_data_snapshot s
    ) z
) y;

-- 5C.1 Initiated vs processing vs completed (count and value)
SELECT refund_status, settlement_status,
       COUNT(*)                                                    AS refunds,
       ROUND(100 * COUNT(*) / (SELECT COUNT(*) FROM vw_refund_reconciliation), 2)  AS pct_of_refunds,
       ROUND(SUM(refund_amount), 2)                                AS refund_value,
       ROUND(100 * SUM(refund_amount) / (SELECT SUM(refund_amount) FROM vw_refund_reconciliation), 2) AS pct_of_value
FROM   vw_refund_reconciliation
GROUP  BY refund_status, settlement_status
ORDER  BY FIELD(refund_status, 'INITIATED', 'PROCESSING', 'COMPLETED');

-- 5C.2 Refund completion by gateway
SELECT gateway_name,
       COUNT(*)                                                    AS refunds,
       SUM(refund_status = 'INITIATED')                            AS initiated,
       SUM(refund_status = 'PROCESSING')                           AS processing,
       SUM(refund_status = 'COMPLETED')                            AS completed,
       ROUND(100 * SUM(refund_status = 'COMPLETED') / COUNT(*), 2) AS completion_rate_pct,
       ROUND(SUM(refund_amount), 2)                                AS refund_value,
       ROUND(SUM(completed_amount), 2)                             AS completed_value,
       ROUND(SUM(unsettled_amount), 2)                             AS unsettled_value,
       ROUND(100 * SUM(unsettled_amount) / SUM(refund_amount), 2)  AS unsettled_pct_of_value,
       RANK() OVER (ORDER BY SUM(refund_status = 'COMPLETED') / COUNT(*) DESC) AS completion_rank
FROM   vw_refund_reconciliation
GROUP  BY gateway_name
ORDER  BY completion_rank;

-- 5C.3 Refund completion by payment method
SELECT payment_method,
       COUNT(*)                                                    AS refunds,
       SUM(refund_status = 'INITIATED')                            AS initiated,
       SUM(refund_status = 'PROCESSING')                           AS processing,
       SUM(refund_status = 'COMPLETED')                            AS completed,
       ROUND(100 * SUM(refund_status = 'COMPLETED') / COUNT(*), 2) AS completion_rate_pct,
       ROUND(SUM(refund_amount), 2)                                AS refund_value,
       ROUND(SUM(unsettled_amount), 2)                             AS unsettled_value,
       RANK() OVER (ORDER BY SUM(refund_status = 'COMPLETED') / COUNT(*) DESC) AS completion_rank
FROM   vw_refund_reconciliation
GROUP  BY payment_method
ORDER  BY completion_rank;

-- 5C.4 Refund rate: how much of successful revenue is refunded?
SELECT 'Gateway' AS dimension, c.gateway_name AS segment,
       SUM(c.status = 'SUCCESS')                                   AS successful_txns,
       COUNT(r.refund_id)                                          AS refunds,
       ROUND(100 * COUNT(r.refund_id) / SUM(c.status = 'SUCCESS'), 2) AS refund_rate_pct,
       ROUND(SUM(CASE WHEN c.status = 'SUCCESS' THEN c.amount ELSE 0 END), 2) AS successful_value,
       ROUND(IFNULL(SUM(r.refund_amount), 0), 2)                   AS refunded_value,
       ROUND(100 * IFNULL(SUM(r.refund_amount), 0) / SUM(CASE WHEN c.status = 'SUCCESS' THEN c.amount ELSE 0 END), 2) AS refunded_pct_of_value
FROM   vw_transactions_clean c
LEFT JOIN refunds_settlements r ON r.transaction_id = c.transaction_id
GROUP  BY c.gateway_name
UNION ALL
SELECT 'Payment method', c.payment_method,
       SUM(c.status = 'SUCCESS'),
       COUNT(r.refund_id),
       ROUND(100 * COUNT(r.refund_id) / SUM(c.status = 'SUCCESS'), 2),
       ROUND(SUM(CASE WHEN c.status = 'SUCCESS' THEN c.amount ELSE 0 END), 2),
       ROUND(IFNULL(SUM(r.refund_amount), 0), 2),
       ROUND(100 * IFNULL(SUM(r.refund_amount), 0) / SUM(CASE WHEN c.status = 'SUCCESS' THEN c.amount ELSE 0 END), 2)
FROM   vw_transactions_clean c
LEFT JOIN refunds_settlements r ON r.transaction_id = c.transaction_id
GROUP  BY c.payment_method
ORDER  BY dimension, refund_rate_pct DESC;

-- 5C.5 Unsettled refunds by age (how long has the money been owed?)
SELECT age_bucket,
       COUNT(*)                                                    AS unsettled_refunds,
       ROUND(SUM(unsettled_amount), 2)                             AS unsettled_value,
       ROUND(100 * SUM(unsettled_amount) /
             (SELECT SUM(unsettled_amount) FROM vw_refund_reconciliation), 2) AS pct_of_unsettled_value,
       SUM(refund_status = 'INITIATED')                            AS still_initiated,
       SUM(refund_status = 'PROCESSING')                           AS in_processing
FROM   vw_refund_reconciliation
WHERE  settlement_status = 'UNSETTLED'
GROUP  BY age_bucket
ORDER  BY age_bucket;

-- 5C.6 Reconciliation ledger by gateway
WITH l AS (
    SELECT c.gateway_name,
           SUM(CASE WHEN c.status = 'SUCCESS' THEN c.amount ELSE 0 END)           AS gross_successful,
           IFNULL(SUM(r.refund_amount), 0)                                        AS refunds_requested,
           IFNULL(SUM(CASE WHEN r.refund_status = 'COMPLETED'  THEN r.refund_amount END), 0) AS refunds_completed,
           IFNULL(SUM(CASE WHEN r.settlement_status = 'UNSETTLED' THEN r.refund_amount END), 0) AS refunds_unsettled
    FROM   vw_transactions_clean c
    LEFT JOIN refunds_settlements r ON r.transaction_id = c.transaction_id
    GROUP  BY c.gateway_name
)
SELECT gateway_name,
       ROUND(gross_successful, 2)                                  AS gross_successful_revenue,
       ROUND(refunds_requested, 2)                                 AS refunds_requested,
       ROUND(refunds_completed, 2)                                 AS refunds_completed_settled,
       ROUND(refunds_unsettled, 2)                                 AS refunds_unsettled_liability,
       ROUND(gross_successful - refunds_completed, 2)              AS net_after_completed_refunds,
       ROUND(gross_successful - refunds_requested, 2)              AS net_if_all_refunds_complete,
       ROUND(100 * refunds_unsettled / refunds_requested, 2)       AS pct_refund_value_unsettled
FROM   l
UNION ALL
SELECT 'ALL GATEWAYS',
       ROUND(SUM(gross_successful), 2), ROUND(SUM(refunds_requested), 2),
       ROUND(SUM(refunds_completed), 2), ROUND(SUM(refunds_unsettled), 2),
       ROUND(SUM(gross_successful) - SUM(refunds_completed), 2),
       ROUND(SUM(gross_successful) - SUM(refunds_requested), 2),
       ROUND(100 * SUM(refunds_unsettled) / SUM(refunds_requested), 2)
FROM   l;

-- 5C.7 Exceptions summary: which refunds need investigation?
SELECT recon_status,
       needs_investigation,
       COUNT(*)                                                    AS refunds,
       ROUND(SUM(refund_amount), 2)                                AS refund_value,
       ROUND(AVG(refund_age_days), 1)                              AS avg_age_days
FROM   vw_refund_reconciliation
GROUP  BY recon_status, needs_investigation
ORDER  BY needs_investigation DESC, refunds DESC;

-- 5C.8 Investigation load by gateway and payment method
SELECT gateway_name, payment_method,
       COUNT(*)                                                    AS refunds,
       SUM(needs_investigation)                                    AS need_investigation,
       ROUND(100 * SUM(needs_investigation) / COUNT(*), 2)         AS pct_need_investigation,
       ROUND(SUM(CASE WHEN needs_investigation = 1 THEN refund_amount ELSE 0 END), 2) AS value_to_investigate
FROM   vw_refund_reconciliation
GROUP  BY gateway_name, payment_method
ORDER  BY value_to_investigate DESC;

-- 5C.9 Investigation work-list: the 25 highest-value aged / mismatched refunds
SELECT refund_id, transaction_id, customer_id, gateway_name, payment_method,
       refund_amount, refund_status, settlement_status, requested_at,
       refund_age_days, recon_status
FROM   vw_refund_reconciliation
WHERE  needs_investigation = 1
ORDER  BY refund_amount DESC, refund_age_days DESC
LIMIT  25;

-- 5C.10 How fast do customers ask for refunds after paying?
SELECT CASE WHEN hours_payment_to_refund < 12 THEN '1) under 12 h'
            WHEN hours_payment_to_refund < 24 THEN '2) 12-24 h'
            WHEN hours_payment_to_refund < 36 THEN '3) 24-36 h'
            ELSE                                   '4) 36-48 h' END AS refund_request_delay,
       COUNT(*)                                                     AS refunds,
       ROUND(SUM(refund_amount), 2)                                 AS refund_value
FROM   vw_refund_reconciliation
GROUP  BY refund_request_delay
ORDER  BY refund_request_delay;

-- 5C.11 Monthly refund requests: initiated vs completed
SELECT refund_month,
       COUNT(*)                                                    AS refunds_requested,
       SUM(refund_status = 'COMPLETED')                            AS completed,
       SUM(refund_status <> 'COMPLETED')                           AS still_open,
       ROUND(100 * SUM(refund_status = 'COMPLETED') / COUNT(*), 2) AS completion_rate_pct,
       ROUND(SUM(refund_amount), 2)                                AS refund_value,
       ROUND(SUM(unsettled_amount), 2)                             AS unsettled_value
FROM   vw_refund_reconciliation
GROUP  BY refund_month
ORDER  BY refund_month;

-- =====================================================================
-- PART 5D | SETTLEMENT GAP ANALYSIS  (captured amount vs gateway payout)
-- =====================================================================
-- The original data has no gateway settlement file, so one is built here:
--   * vw_gateway_daily_net     = what WE captured per gateway per day, net of completed refunds
--   * gateway_settlements      = SYNTHETIC gateway payout file (one batch per gateway per capture
--                                day, paid T+2, 2% gateway fee). About 1 batch in 17 is short-paid
--                                and 1 in 23 is never paid. The anomalies are injected with CRC32 of
--                                the batch id, so every re-run produces the same data.
--   * vw_settlement_gap        = expected payout vs reported payout, one row per batch.
-- Replace the INSERT below with a LOAD DATA of a real Razorpay / Cashfree / PayU settlement report
-- (same six columns) to run the same analysis on real files.

CREATE OR REPLACE VIEW vw_gateway_daily_net AS
SELECT  c.gateway_name,
        c.txn_date,
        COUNT(*)                                                      AS successful_txns,
        ROUND(SUM(c.amount), 2)                                       AS captured_amount,
        ROUND(SUM(IFNULL(rf.completed_refund, 0)), 2)                 AS completed_refunds
FROM    vw_transactions_clean c
LEFT JOIN (SELECT transaction_id,
                  SUM(CASE WHEN refund_status = 'COMPLETED' THEN refund_amount ELSE 0 END) AS completed_refund
           FROM   refunds_settlements
           GROUP  BY transaction_id) rf ON rf.transaction_id = c.transaction_id
WHERE   c.status = 'SUCCESS'
GROUP   BY c.gateway_name, c.txn_date;

DROP TABLE IF EXISTS gateway_settlements;
CREATE TABLE gateway_settlements (
    settlement_batch_id  VARCHAR(30)    NOT NULL,
    gateway_name         VARCHAR(20)    NOT NULL,
    capture_date         DATE           NOT NULL,
    settlement_date      DATE           NOT NULL,   -- scheduled payout date (capture_date + 2 days)
    gateway_fee          DECIMAL(14,2)  NOT NULL,
    payout_amount        DECIMAL(14,2)  NULL,       -- NULL = no payout reported in the settlement file
    PRIMARY KEY (settlement_batch_id)
);

SELECT  k.batch_id,
        k.gateway_name,
        k.txn_date,
        DATE_ADD(k.txn_date, INTERVAL 2 DAY),
        k.fee,
        CASE WHEN DATE_ADD(k.txn_date, INTERVAL 2 DAY) > DATE(s.as_of) THEN NULL          -- not due yet
             WHEN MOD(CRC32(k.batch_id), 23) = 0                       THEN NULL          -- never paid
             WHEN MOD(CRC32(k.batch_id), 17) = 1                       THEN ROUND(k.expected * 0.97, 2)  -- short-paid
             ELSE k.expected END
FROM   (SELECT d.gateway_name,
               d.txn_date,
               CONCAT('STL_', UPPER(LEFT(d.gateway_name, 3)), '_', DATE_FORMAT(d.txn_date, '%Y%m%d')) AS batch_id,
               ROUND(d.captured_amount * 0.02, 2)                                                    AS fee,
               ROUND(d.captured_amount - d.completed_refunds - ROUND(d.captured_amount * 0.02, 2), 2) AS expected
        FROM   vw_gateway_daily_net d) k
CROSS JOIN vw_data_snapshot s;

CREATE OR REPLACE VIEW vw_settlement_gap AS
SELECT  y.*,
        CASE WHEN y.settlement_check IN ('IN TRANSIT', 'MATCHED') THEN 0 ELSE 1 END AS needs_investigation
FROM (
    SELECT  a.*,
            CASE WHEN a.payout_amount IS NULL AND a.settlement_date > a.snapshot_date THEN 0
                 ELSE ROUND(a.expected_payout - IFNULL(a.payout_amount, 0), 2) END   AS gap_amount,
            CASE WHEN a.payout_amount IS NULL AND a.settlement_date > a.snapshot_date THEN 'IN TRANSIT'
                 WHEN a.payout_amount IS NULL                                         THEN 'NOT SETTLED: payout overdue'
                 WHEN ABS(a.expected_payout - a.payout_amount) < 0.01                 THEN 'MATCHED'
                 WHEN a.payout_amount < a.expected_payout                             THEN 'SHORT-SETTLED'
                 ELSE 'OVER-SETTLED' END                                              AS settlement_check
    FROM (
        SELECT  g.settlement_batch_id,
                g.gateway_name,
                g.capture_date,
                g.settlement_date,
                d.successful_txns,
                d.captured_amount,
                d.completed_refunds,
                g.gateway_fee,
                ROUND(d.captured_amount - d.completed_refunds - g.gateway_fee, 2)    AS expected_payout,
                g.payout_amount,
                DATE(s.as_of)                                                        AS snapshot_date,
                GREATEST(DATEDIFF(DATE(s.as_of), g.settlement_date), 0)              AS days_past_due
        FROM    gateway_settlements g
        JOIN    vw_gateway_daily_net d ON d.gateway_name = g.gateway_name
                                      AND d.txn_date     = g.capture_date
        CROSS JOIN vw_data_snapshot s
    ) a
) y;

-- 5D.1 Settlement gap by gateway: expected payout vs payout received
SELECT IFNULL(gateway_name, 'ALL GATEWAYS')                                  AS gateway_name,
       COUNT(*)                                                              AS batches,
       SUM(settlement_check = 'MATCHED')                                     AS matched,
       SUM(settlement_check = 'SHORT-SETTLED')                               AS short_settled,
       SUM(settlement_check LIKE 'NOT SETTLED%')                             AS not_settled,
       SUM(settlement_check = 'IN TRANSIT')                                  AS in_transit,
       ROUND(SUM(expected_payout), 2)                                        AS expected_payout,
       ROUND(SUM(IFNULL(payout_amount, 0)), 2)                               AS payout_received,
       ROUND(SUM(gap_amount), 2)                                             AS unsettled_gap,
       ROUND(100 * SUM(gap_amount) /
             NULLIF(SUM(CASE WHEN settlement_check <> 'IN TRANSIT' THEN expected_payout ELSE 0 END), 0), 2) AS gap_pct_of_due_payout
FROM   vw_settlement_gap
GROUP  BY gateway_name WITH ROLLUP;

-- 5D.2 Monthly settlement gap
SELECT DATE_FORMAT(capture_date, '%Y-%m')                                    AS capture_month,
       COUNT(*)                                                              AS batches,
       SUM(needs_investigation)                                              AS batches_to_investigate,
       ROUND(SUM(expected_payout), 2)                                        AS expected_payout,
       ROUND(SUM(IFNULL(payout_amount, 0)), 2)                               AS payout_received,
       ROUND(SUM(gap_amount), 2)                                             AS unsettled_gap
FROM   vw_settlement_gap
GROUP  BY capture_month
ORDER  BY capture_month;

-- 5D.3 Settlement investigation work-list: the 25 largest gaps
SELECT settlement_batch_id, gateway_name, capture_date, settlement_date, successful_txns,
       expected_payout, payout_amount, gap_amount, days_past_due, settlement_check
FROM   vw_settlement_gap
WHERE  needs_investigation = 1
ORDER  BY ABS(gap_amount) DESC
LIMIT  25;

-- =====================================================================
-- PART 5E | REFUND SLA (BUSINESS DAYS) AND CLEANING EXCEPTIONS
-- =====================================================================
-- 5E.1 Open refunds by business days since the request (SLA: 3-5 business days)
SELECT CASE WHEN business_days_open < 3  THEN '1) under 3 business days'
            WHEN business_days_open <= 5 THEN '2) 3-5 business days'
            ELSE                              '3) over 5 business days' END   AS refund_open_band,
       COUNT(*)                                                               AS open_refunds,
       ROUND(SUM(refund_amount), 2)                                           AS open_value,
       SUM(refund_status = 'INITIATED')                                       AS still_initiated,
       SUM(refund_status = 'PROCESSING')                                      AS in_processing,
       SUM(settlement_status = 'UNSETTLED')                                   AS unsettled
FROM   vw_refund_reconciliation
WHERE  refund_status <> 'COMPLETED'
GROUP  BY refund_open_band
ORDER  BY refund_open_band;

-- 5E.2 Open refunds over 5 business days, by gateway
SELECT gateway_name,
       COUNT(*)                                                               AS open_refunds,
       SUM(business_days_open > 5)                                            AS stuck_over_5_bd,
       ROUND(100 * SUM(business_days_open > 5) / COUNT(*), 2)                 AS pct_stuck,
       ROUND(SUM(CASE WHEN business_days_open > 5 THEN refund_amount ELSE 0 END), 2) AS value_stuck
FROM   vw_refund_reconciliation
WHERE  refund_status <> 'COMPLETED'
GROUP  BY gateway_name
ORDER  BY value_stuck DESC;

-- 5E.3 Refunds that exceeded the original payment (capped during cleaning step 5.2)
SELECT refund_id, transaction_id, gateway_name, payment_method,
       txn_amount, refund_amount_as_requested, refund_amount                  AS refund_amount_after_cap,
       ROUND(refund_amount_as_requested - refund_amount, 2)                   AS excess_refund
FROM   vw_refund_reconciliation
WHERE  was_capped_in_cleaning = 1
ORDER  BY excess_refund DESC;

-- =====================================================================
-- PART 5F | RECONCILIATION AUDIT LIST  (items needing manual investigation)
-- =====================================================================
-- One list, three exception types:
--   DEBIT_NOT_CAPTURED : payment still PENDING at the gateway (customer may be debited, money not captured)
--   REFUND_EXCEPTION   : refund mismatched, aged, or stuck over 5 business days
--   SETTLEMENT_GAP     : gateway payout short, over, or overdue for a capture day
-- Priority: P1 = act now, P2 = investigate this week, P3 = monitor.
CREATE OR REPLACE VIEW vw_reconciliation_audit AS
SELECT  'DEBIT_NOT_CAPTURED'                                                  AS audit_type,
        p.transaction_id                                                      AS reference_id,
        p.transaction_id                                                      AS transaction_id,
        p.gateway_name,
        p.payment_method,
        p.customer_id,
        p.amount                                                              AS amount_at_risk,
        p.created_at                                                          AS event_time,
        p.unresolved_days_at_snapshot                                         AS age_days,
        CASE WHEN p.paid_again_within_24h = 1
             THEN 'Pending at gateway and customer paid again within 24h (possible double debit)'
             ELSE 'Pending at gateway: customer may be debited but payment not captured' END AS issue,
        CASE WHEN p.paid_again_within_24h = 1 THEN 'P1'
             WHEN p.age_minutes_at_snapshot > 30 THEN 'P2'
             ELSE 'P3' END                                                    AS priority
FROM    vw_pending_monitor p
UNION ALL
SELECT  'REFUND_EXCEPTION',
        r.refund_id,
        r.transaction_id,
        r.gateway_name,
        r.payment_method,
        r.customer_id,
        r.refund_amount,
        r.requested_at,
        r.refund_age_days,
        r.recon_status,
        CASE WHEN r.recon_status LIKE 'MISMATCH%' THEN 'P1'
             WHEN r.recon_status LIKE 'AGED%'     THEN 'P2'
             ELSE 'P3' END
FROM    vw_refund_reconciliation r
WHERE   r.needs_investigation = 1
UNION ALL
SELECT  'SETTLEMENT_GAP',
        g.settlement_batch_id,
        NULL,
        g.gateway_name,
        NULL,
        NULL,
        ABS(g.gap_amount),
        CAST(g.settlement_date AS DATETIME),
        g.days_past_due,
        g.settlement_check,
        CASE WHEN g.settlement_check LIKE 'NOT SETTLED%' THEN 'P1' ELSE 'P2' END
FROM    vw_settlement_gap g
WHERE   g.needs_investigation = 1;

-- 5F.1 Audit summary: how much needs investigation?
SELECT audit_type, priority,
       COUNT(*)                                                               AS items,
       ROUND(SUM(amount_at_risk), 2)                                          AS amount_at_risk
FROM   vw_reconciliation_audit
GROUP  BY audit_type, priority
ORDER  BY audit_type, priority;

-- 5F.2 Audit list: the 50 highest-priority, highest-value items
SELECT audit_type, reference_id, transaction_id, gateway_name, payment_method, customer_id,
       amount_at_risk, event_time, age_days, issue, priority
FROM   vw_reconciliation_audit
ORDER  BY priority, amount_at_risk DESC
LIMIT  50;

-- 5F.3 Audit load by gateway
SELECT gateway_name,
       COUNT(*)                                                               AS items,
       SUM(priority = 'P1')                                                   AS p1_items,
       ROUND(SUM(amount_at_risk), 2)                                          AS amount_at_risk,
       ROUND(SUM(CASE WHEN priority = 'P1' THEN amount_at_risk ELSE 0 END), 2) AS p1_amount_at_risk
FROM   vw_reconciliation_audit
GROUP  BY gateway_name
ORDER  BY amount_at_risk DESC;
